function.arguments:
{"command": "cd /workspace && cat > /tmp/ob.py <<'EOF'
import subprocess, time, selectors, fcntl, os, sys
def run(args, timeout=8):
    p = subprocess.Popen(["/workspace/executable"]+args,
                     stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False)
    t0=time.time()
    fds = {}
    for name, f in (("OUT", p.stdout), ("ERR", p.stderr)):
        fd=f.fileno(); fl=fcntl.fcntl(fd,fcntl.F_GETFL); fcntl.fcntl(fd,fcntl.F_SETFL,fl|os.O_NONBLOCK)
        fds[fd]=name
    sel=selectors.DefaultSelector()
    for fd in fds: sel.register(fd, selectors.EVENT_READ, fds[fd])
    open_fds=set(fds)
    events=[]
    while open_fds:
        for k,_ in sel.select(timeout):
            data=os.read(k.fd,65536)
            if not data:
                sel.unregister(k.fd); open_fds.discard(k.fd); continue
            events.append((round(time.time()-t0,3), fds[k.fd], data))
    p.wait()
    return events, p.returncode
for args in sys.argv[1:]:
    ev, rc = run(args.split("|"))
    print(f"ARGS {args!r} rc={rc}")
    for e in ev: print("   ", e)
