// A small regular expression engine, API-compatible (for the subset we need)
// with the `regex` crate: compile from a pattern, then `is_match` on a line.
//
// Supported syntax:
//   literals, `.`, `[...]` (with ranges, negation, escapes, POSIX classes and
//   nested classes), `\d \D \w \W \s \S \b \B`, anchors `^ $ \A \z \Z`,
//   groups `( )` `(?: )` `(?P<name> )`, inline flags `(?i)`, `(?i:...)`,
//   alternation `|`, repetition `* + ? {n} {n,} {n,m}` with optional laziness,
//   escapes `\n \t \r \f \v \a \0 \xNN \x{...} \uNNNN \\ \. ...`,
//   unicode properties `\p{..}` / `\pN` / `\P{..}`.

#[derive(Clone, Copy, PartialEq)]
pub enum Posix {
    Alnum,
    Alpha,
    Ascii,
    Blank,
    Cntrl,
    Digit,
    Graph,
    Lower,
    Print,
    Punct,
    Space,
    Upper,
    Word,
    Xdigit,
}

#[derive(Clone)]
pub enum Item {
    Range(char, char),
    Posix(Posix),
    Class(Class),
}

#[derive(Clone)]
pub struct Class {
    pub items: Vec<Item>,
    pub neg: bool,
}

#[derive(Clone)]
pub enum Node {
    Lit(char),
    Any,
    Class(Class),
    StartLine,
    EndLine,
    StartText,
    EndText,
    WordB,
    NotWordB,
    Group(Vec<Node>),
    Alt(Vec<Vec<Node>>),
    Rep {
        seq: Vec<Node>,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    },
}

pub struct RegexError {
    pub pattern: String,
    pub spans: Vec<(usize, usize)>,
    pub msg: String,
}

impl std::fmt::Display for RegexError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        let mut line = String::new();
        let mut idx = 0usize;
        let mut spans = self.spans.clone();
        spans.sort();
        for (s, e) in spans.iter() {
            if *s > idx {
                for _ in idx..*s {
                    line.push(' ');
                }
            }
            let width = if e > s { e - s } else { 1 };
            for _ in 0..width {
                line.push('^');
            }
            idx = *s + width;
        }
        write!(
            f,
            "regex parse error:\n    {}\n    {}\nerror: {}",
            self.pattern, line, self.msg
        )
    }
}

pub struct Regex {
    root: Node,
}

// ---------------------------------------------------------------- properties

fn posix_match(p: Posix, c: char) -> bool {
    match p {
        Posix::Alnum => c.is_alphanumeric(),
        Posix::Alpha => c.is_alphabetic(),
        Posix::Ascii => c.is_ascii(),
        Posix::Blank => c == ' ' || c == '\t',
        Posix::Cntrl => c.is_control(),
        Posix::Digit => c.is_numeric(),
        Posix::Graph => c.is_ascii_graphic() || (!c.is_whitespace() && !c.is_control() && !c.is_ascii()),
        Posix::Lower => c.is_lowercase(),
        Posix::Print => !c.is_control(),
        Posix::Punct => c.is_ascii_punctuation()
            || (!c.is_alphanumeric() && !c.is_whitespace() && !c.is_control()),
        Posix::Space => c.is_whitespace(),
        Posix::Upper => c.is_uppercase(),
        Posix::Word => c.is_alphanumeric() || c == '_',
        Posix::Xdigit => c.is_ascii_hexdigit(),
    }
}

fn prop_match(name: &str, c: char) -> bool {
    // single letter and two letter general categories plus a handful of names
    let n = name.trim();
    let up = n.to_uppercase();
    match up.as_str() {
        "L" | "LETTER" => c.is_alphabetic(),
        "LU" | "UPPERCASE_LETTER" => c.is_uppercase(),
        "LL" | "LOWERCASE_LETTER" => c.is_lowercase(),
        "LT" => c.is_uppercase(),
        "LM" | "LO" | "LC" => c.is_alphabetic(),
        "N" | "NUMBER" => c.is_numeric(),
        "ND" | "DECIMAL_NUMBER" => c.is_numeric(),
        "NL" | "NO" => c.is_numeric(),
        "P" | "PUNCTUATION" => !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control(),
        "S" | "SYMBOL" => !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control(),
        "Z" | "ZS" | "SEPARATOR" | "SPACE_SEPARATOR" => c.is_whitespace() && !c.is_control(),
        "C" | "CC" | "CONTROL" => c.is_control(),
        "M" | "MARK" => false,
        "ALPHA" | "ALPHABETIC" => c.is_alphabetic(),
        "ALNUM" => c.is_alphanumeric(),
        "DIGIT" => c.is_numeric(),
        "SPACE" => c.is_whitespace(),
        "UPPER" | "UPPERCASE" => c.is_uppercase(),
        "LOWER" | "LOWERCASE" => c.is_lowercase(),
        "WORD" => c.is_alphanumeric() || c == '_',
        "BLANK" => c == ' ' || c == '\t',
        "CNTRL" => c.is_control(),
        "PRINT" => !c.is_control(),
        "PUNCT" => !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control(),
        "GRAPHEMES" | "ANY" => true,
        _ => {
            // scripts and other names we cannot table: accept letters
            let l = n.to_lowercase();
            match l.as_str() {
                "latin" => c.is_alphabetic(),
                "greek" => c.is_alphabetic(),
                "cyrillic" => c.is_alphabetic(),
                "han" => c.is_alphabetic(),
                "hiragana" => c.is_alphabetic(),
                "katakana" => c.is_alphabetic(),
                "arabic" => c.is_alphabetic(),
                "hebrew" => c.is_alphabetic(),
                "ascii" => c.is_ascii(),
                "ascii_alphabetic" => c.is_ascii_alphabetic(),
                "ascii_alphanumeric" => c.is_ascii_alphanumeric(),
                "ascii_digit" => c.is_ascii_digit(),
                "ascii_lowercase" => c.is_ascii_lowercase(),
                "ascii_uppercase" => c.is_ascii_uppercase(),
                "ascii_punctuation" => c.is_ascii_punctuation(),
                "ascii_whitespace" => c.is_ascii_whitespace(),
                "ascii_graphic" => c.is_ascii_graphic(),
                "ascii_hexdigit" => c.is_ascii_hexdigit(),
                "ascii_control" => c.is_ascii_control(),
                _ => false,
            }
        }
    }
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

impl Class {
    fn raw_match(&self, c: char) -> bool {
        let mut hit = false;
        for it in self.items.iter() {
            let m = match it {
                Item::Range(a, b) => c >= *a && c <= *b,
                Item::Posix(p) => posix_match(*p, c),
                Item::Class(cl) => cl.raw_match(c),
            };
            if m {
                hit = true;
                break;
            }
        }
        if self.neg {
            !hit
        } else {
            hit
        }
    }
    fn matches(&self, c: char, ci: bool) -> bool {
        if self.raw_match(c) {
            return true;
        }
        if ci {
            for alt in case_variants(c) {
                if alt != c && self.raw_match(alt) {
                    return true;
                }
            }
        }
        false
    }
}

fn case_variants(c: char) -> Vec<char> {
    let mut v = Vec::new();
    for ch in c.to_lowercase() {
        v.push(ch);
    }
    for ch in c.to_uppercase() {
        v.push(ch);
    }
    if c.is_ascii_alphabetic() {
        v.push(c.to_ascii_uppercase());
        v.push(c.to_ascii_lowercase());
    }
    v
}

fn ci_eq(a: char, b: char) -> bool {
    if a == b {
        return true;
    }
    let mut la = a.to_lowercase();
    let mut lb = b.to_lowercase();
    loop {
        match (la.next(), lb.next()) {
            (None, None) => return true,
            (Some(x), Some(y)) => {
                if x != y {
                    // try simple ascii case
                    return a.to_ascii_lowercase() == b.to_ascii_lowercase()
                        && a.to_ascii_uppercase() == b.to_ascii_uppercase();
                }
            }
            _ => return false,
        }
    }
}

// ---------------------------------------------------------------- parser

struct Flags {
    ci: bool,
    swap: bool,
    x: bool,
}

impl Flags {
    fn new() -> Flags {
        Flags {
            ci: false,
            swap: false,
            x: false,
        }
    }
}

struct Parser {
    pat: String,
    c: Vec<char>,
    i: usize,
    flags: Flags,
    names: Vec<String>,
    depth: usize,
}

type R<T> = Result<T, RegexError>;

impl Parser {
    fn err(&self, msg: &str, spans: Vec<(usize, usize)>) -> RegexError {
        RegexError {
            pattern: self.pat.clone(),
            spans,
            msg: msg.to_string(),
        }
    }
    fn e1(&self, msg: &str, s: usize) -> RegexError {
        self.err(msg, vec![(s, s + 1)])
    }
    fn peek(&self) -> Option<char> {
        self.c.get(self.i).copied()
    }
    fn peek_at(&self, k: usize) -> Option<char> {
        self.c.get(self.i + k).copied()
    }
    fn bump(&mut self) {
        self.i += 1;
    }
    fn skip_x(&mut self) {
        if !self.flags.x {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.bump();
                }
                Some('#') => {
                    while let Some(c) = self.peek() {
                        self.bump();
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    fn parse(&mut self) -> R<Node> {
        let branches = self.alt()?;
        if let Some(p) = self.peek() {
            // leftover ')' at the top level
            return Err(self.e1("unopened group", self.i));
        }
        Ok(Node::Alt(branches))
    }

    fn alt(&mut self) -> R<Vec<Vec<Node>>> {
        let mut branches = Vec::new();
        loop {
            self.skip_x();
            branches.push(self.seq()?);
            self.skip_x();
            if self.peek() == Some('|') {
                self.bump();
                continue;
            }
            break;
        }
        Ok(branches)
    }

    fn seq(&mut self) -> R<Vec<Node>> {
        let mut out: Vec<Node> = Vec::new();
        loop {
            self.skip_x();
            match self.peek() {
                None | Some('|') | Some(')') => break,
                Some('*') | Some('+') | Some('?') | Some('{') => {
                    let p = self.i;
                    return Err(self.e1("repetition operator missing expression", p));
                }
                _ => {}
            }
            let atom = self.atom()?;
            let node = self.quantifiers(atom)?;
            out.push(node);
        }
        Ok(out)
    }

    fn quantifiers(&mut self, atom: Node) -> R<Node> {
        let mut node = atom;
        loop {
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.bump();
                    (0u32, None)
                }
                Some('+') => {
                    self.bump();
                    (1u32, None)
                }
                Some('?') => {
                    self.bump();
                    (0u32, Some(1u32))
                }
                Some('{') => match self.counted()? {
                    Some((a, b)) => (a, b),
                    None => break,
                },
                _ => break,
            };
            let mut greedy = !self.flags.swap;
            if self.peek() == Some('?') {
                self.bump();
                greedy = !greedy;
            }
            node = Node::Rep {
                seq: vec![node],
                min,
                max,
                greedy,
            };
        }
        Ok(node)
    }

    // returns None when the brace is meant literally
    fn counted(&mut self) -> R<Option<(u32, Option<u32>)>> {
        let open = self.i;
        self.bump(); // consume '{'
        let first = match self.peek() {
            Some(c) if c.is_ascii_digit() => {
                let mut n: u64 = 0;
                let mut any = false;
                while let Some(c) = self.peek() {
                    if let Some(d) = c.to_digit(10) {
                        n = n * 10 + d as u64;
                        any = true;
                        self.bump();
                    } else {
                        break;
                    }
                }
                if !any {
                    return Err(self.e1("repetition quantifier expects a valid decimal", self.i));
                }
                if n > 100000 {
                    return Err(self.e1("repetition quantifier expects a valid decimal", open + 1));
                }
                n
            }
            Some(_) => {
                return Err(self.e1("repetition quantifier expects a valid decimal", self.i));
            }
            None => {
                return Err(self.err(
                    "unclosed counted repetition",
                    vec![(open, self.i)],
                ));
            }
        };
        let mut second: Option<u64> = None;
        if self.peek() == Some(',') {
            self.bump();
            if self.peek() == Some('}') {
                second = None;
            } else {
                let mut n: u64 = 0;
                let mut any = false;
                while let Some(c) = self.peek() {
                    if let Some(d) = c.to_digit(10) {
                        n = n * 10 + d as u64;
                        any = true;
                        self.bump();
                    } else {
                        break;
                    }
                }
                if !any {
                    return Err(self.e1("repetition quantifier expects a valid decimal", self.i));
                }
                second = Some(n);
            }
        }
        if self.peek() != Some('}') {
            return Err(self.err("unclosed counted repetition", vec![(open, self.i)]));
        }
        self.bump(); // consume '}'
        // laziness marker is consumed by the caller before the range check
        if let Some(hi) = second {
            if hi < first {
                let mut end = self.i;
                if self.peek() == Some('?') {
                    end += 1;
                }
                return Err(self.err(
                    "invalid repetition count range, the start must be <= the end",
                    vec![(open, end)],
                ));
            }
        }
        Ok(Some((
            first as u32,
            second.map(|v| v as u32),
        )))
    }

