            '.' => {
                self.bump();
                Ok(Node::Any)
            }
            '^' => {
                self.bump();
                Ok(Node::StartLine)
            }
            '$' => {
                self.bump();
                Ok(Node::EndLine)
            }
            '[' => self.class(),
            '(' => self.group(),
            '\\' => self.escape(),
            _ => {
                self.bump();
                Ok(Node::Lit(c))
            }
        }
    }

