                                    let first_pos = 0usize; // resolved below
                                    let _ = first_pos;
                                    dup_spans.push((self.i, self.i + 1));
                                    if dup_spans.len() == 2 {
                                        let mut spans = dup_spans.clone();
                                        spans.sort();
                                        return Err(self.err("duplicate flag", spans));
                                    }
                                } else {
                                    seen.push(f);
                                    match f {
                                        'i' => self.flags.ci = !neg,
                                        'U' => self.flags.swap = !neg,
                                        'x' => self.flags.x = !neg,
                                        _ => {}
                                    }
                                }
                                self.bump();
                            }
                            Some(':') => {
                                self.bump();
                                let branches = self.alt()?;
                                if self.peek() != Some(')') {
                                    return Err(self.e1("unclosed group", open));
                                }
                                self.bump();
                                self.flags = saved_flags;
                                return Ok(Node::Alt(branches));
                            }
                            Some(_) => {
                                let p = self.i;
                                let _ = p;
                                return Err(self.e1("unrecognized flag", self.i));
                            }
                        }
                    }
                }
                Some(_) => {
                    let p = self.i;
                    return Err(self.e1("unrecognized flag", p));
                }
                None => {
                    return Err(self.e1("unclosed group", open));
                }
            }
        }
        let branches = self.alt()?;
        if self.peek() != Some(')') {
            return Err(self.e1("unclosed group", open));
        }
        self.bump();
        if reset_at_end {
            self.flags = saved_flags;
        }
        if named.is_some() {
            // fallthrough
        }
        let _ = &saved_flags;
        if branches.len() == 1 {
            Ok(Node::Group(branches.pop().unwrap()))
        } else {
            Ok(Node::Group(vec![Node::Alt(branches)]))
        }
    }

    fn escape(&mut self) -> R<Node> {
        let start = self.i;
        self.bump(); // '\\'
        let c = match self.peek() {
            Some(c) => c,
            None => {
                return Err(self.e1(
                    "incomplete escape sequence, reached end of pattern prematurely",
                    start,
                ));
            }
        };
        self.bump();
        match c {
            'd' | 'D' | 'w' | 'W' | 's' | 'S' | 'p' | 'P' => {
                if c == 'd' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Digit)],
                        neg: false,
                    }));
                }
                if c == 'D' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Digit)],
                        neg: true,
                    }));
                }
                if c == 'w' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Word)],
                        neg: false,
                    }));
                }
                if c == 'W' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Word)],
                        neg: true,
                    }));
                }
                if c == 's' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Space)],
                        neg: false,
                    }));
                }
                if c == 'S' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Space)],
                        neg: true,
                    }));
                }
                // unicode property
                let name: String;
                let mut end = self.i;
                if self.peek() == Some('{') {
                    self.bump();
                    let mut n = String::new();
                    loop {
                        match self.peek() {
                            Some('}') => {
                                self.bump();
                                break;
                            }
                            Some(ch) => {
                                n.push(ch);
                                self.bump();
                            }
                            None => {
                                return Err(self.e1(
                                    "unclosed counted repetition",
                                    start,
                                ));
                            }
                        }
                    }
                    name = n;
                    end = self.i;
                } else {
                    match self.peek() {
                        Some(ch) if ch.is_ascii_alphabetic() => {
                            name = ch.to_string();
                            self.bump();
                            end = self.i;
                        }
                        _ => {
                            return Err(self.e1(
                                "incomplete escape sequence, reached end of pattern prematurely",
                                end,
                            ));
                        }
                    }
                }
                let neg = c == 'P';
                if !prop_match(&name, 'a') && !prop_match(&name, '0') && !prop_match(&name, ' ') {
                    if !known_property(&name) {
                        return Err(self.err(
                            "Unicode property not found",
                            vec![(start, end)],
                        ));
                    }
                }
                Ok(Node::Class(Class {
                    items: vec![Item::Prop(name)],
                    neg,
                }))
            }
            'b' => Ok(Node::WordB),
            'B' => Ok(Node::NotWordB),
            'A' => Ok(Node::StartText),
            'z' => Ok(Node::EndText),
            'Z' => Ok(Node::EndText),
            'n' => Ok(Node::Lit('\n')),
            'r' => Ok(Node::Lit('\r')),
            't' => Ok(Node::Lit('\t')),
            'f' => Ok(Node::Lit('\u{c}')),
            'v' => Ok(Node::Lit('\u{b}')),
            'a' => Ok(Node::Lit('\u{7}')),
            '0' => Ok(Node::Lit('\0')),
            'x' => {
                let mut v: u32 = 0;
                if self.peek() == Some('{') {
                    self.bump();
                    let mut any = false;
                    while let Some(ch) = self.peek() {
                        if ch == '}' {
                            self.bump();
                            break;
                        }
                        if let Some(d) = ch.to_digit(16) {
                            v = v * 16 + d;
                            any = true;
                            self.bump();
                        } else {
                            return Err(self.e1("invalid hexadecimal digit", self.i));
                        }
                    }
                    if !any {
                        return Err(self.e1("invalid hexadecimal digit", self.i));
                    }
                } else {
                    for _ in 0..2 {
                        match self.peek() {
                            Some(ch) if ch.is_ascii_hexdigit() => {
                                v = v * 16 + ch.to_digit(16).unwrap();
                                self.bump();
                            }
                            _ => {
                                return Err(self.e1(
                                    "incomplete escape sequence, reached end of pattern prematurely",
                                    self.i,
                                ));
                            }
                        }
                    }
                }
                match char::from_u32(v) {
                    Some(ch) => Ok(Node::Lit(ch)),
                    None => Err(self.e1("invalid scalar value", start)),
                }
            }
            'u' => {
                let mut v: u32 = 0;
                for _ in 0..4 {
                    match self.peek() {
                        Some(ch) if ch.is_ascii_hexdigit() => {
                            v = v * 16 + ch.to_digit(16).unwrap();
                            self.bump();
                        }
                        _ => {
                            return Err(self.e1("invalid hexadecimal digit", self.i));
                        }
                    }
                }
                match char::from_u32(v) {
                    Some(ch) => Ok(Node::Lit(ch)),
                    None => Err(self.e1("invalid scalar value", start)),
                }
            }
            '1'..='9' => Err(self.err(
                "backreferences are not supported",
                vec![(start, self.i)],
            )),
            _ => {
                if c.is_ascii_alphanumeric() {
                    return Err(self.err("unrecognized escape sequence", vec![(start, self.i)]));
                }
                Ok(Node::Lit(c))
            }
        }
    }

    fn class(&mut self) -> R<Node> {
        let open = self.i;
        self.bump(); // '['
        let mut neg = false;
        if self.peek() == Some('^') {
            neg = true;
            self.bump();
        }
        let mut items: Vec<Item> = Vec::new();
        let mut first = true;
        let mut consumed_close = false;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => {
                    let mut width = 1;
                    if neg {
                        width += 1;
                    }
                    if consumed_close {
                        width += 1;
                    }
                    return Err(self.err(
                        "unclosed character class",
                        vec![(open, open + width)],
                    ));
                }
            };
            if c == ']' && !first {
                self.bump();
                break;
            }
            if c == ']' && first {
                // literal ']' as the first item
                consumed_close = true;
                self.bump();
                items.push(Item::Range(']', ']'));
                first = false;
                continue;
            }
            first = false;
            if c == '[' {
                // posix class or nested class
                if self.peek_at(1) == Some(':') {
                    // find closing ":]"
                    let save = self.i;
                    let mut j = self.i + 2;
                    let mut negp = false;
                    if self.peek_at(2) == Some('^') {
                        negp = true;
                        j += 1;
                    }
                    let mut name = String::new();
                    let mut found = false;
                    while j < self.c.len() {
                        if self.c[j] == ':' && j + 1 < self.c.len() && self.c[j + 1] == ']' {
                            found = true;
                            break;
                        }
                        name.push(self.c[j]);
                        j += 1;
                    }
                    if found {
                        for k in self.i..=j + 1 {
                            let _ = k;
                        }
                        let p = match posix_by_name(&name) {
                            Some(p) => p,
                            None => {
                                return Err(self.err(
                                    "unrecognized POSIX character class",
                                    vec![(self.i, j + 2)],
                                ));
                            }
                        };
                        items.push(Item::Posix(p));
                        // rewind then advance properly
                        self.i = j + 2;
                        continue;
                    }
                    // not a posix class: nested class
                    self.i = save;
                }
                let nested = self.class()?;
                match nested {
                    Node::Class(cl) => items.push(Item::Class(cl)),
                    _ => {}
                }
                continue;
            }
            if c == '\\' {
                // escape inside class
                let es = self.i;
                self.bump();
                let e = match self.peek() {
                    Some(e) => e,
                    None => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            es,
                        ));
                    }
                };
                self.bump();
                match e {
                    'd' | 'D' | 'w' | 'W' | 's' | 'S' => {
                        let (p, n) = match e {
                            'd' => (Posix::Digit, false),
                            'D' => (Posix::Digit, true),
                            'w' => (Posix::Word, false),
                            'W' => (Posix::Word, true),
                            's' => (Posix::Space, false),
                            _ => (Posix::Space, true),
                        };
                        items.push(Item::Class(Class {
                            items: vec![Item::Posix(p)],
                            neg: n,
                        }));
                    }
                    'p' | 'P' => {
                        let mut name = String::new();
                        let mut end = self.i;
                        if self.peek() == Some('{') {
                            self.bump();
                            while let Some(ch) = self.peek() {
                                if ch == '}' {
                                    self.bump();
                                    break;
                                }
                                name.push(ch);
                                self.bump();
                            }
                            end = self.i;
                        } else if let Some(ch) = self.peek() {
                            name = ch.to_string();
                            self.bump();
                            end = self.i;
                        } else {
                            return Err(self.e1(
                                "incomplete escape sequence, reached end of pattern prematurely",
                                es,
                            ));
                        }
                        if !known_property(&name) {
                            return Err(self.err("Unicode property not found", vec![(es, end)]));
                        }
                        items.push(Item::PropName(name, e == 'P'));
                    }
                    'n' => items.push(Item::Range('\n', '\n')),
                    'r' => items.push(Item::Range('\r', '\r')),
                    't' => items.push(Item::Range('\t', '\t')),
                    'f' => items.push(Item::Range('\u{c}', '\u{c}')),
                    'v' => items.push(Item::Range('\u{b}', '\u{b}')),
                    'a' => items.push(Item::Range('\u{7}', '\u{7}')),
                    'b' => items.push(Item::Range('\u{8}', '\u{8}')),
                    '0' => items.push(Item::Range('\0', '\0')),
                    'x' | 'u' => {
                        let v = self.hex_escape(e)?;
                        match char::from_u32(v) {
                            Some(ch) => items.push(Item::Range(ch, ch)),
                            None => {
                                return Err(self.e1("invalid scalar value", es));
                            }
                        }
                    }
                    other => items.push(Item::Range(other, other)),
                }
                continue;
            }
            // plain char, possible range
            self.bump();
            if self.peek() == Some('-') && self.peek_at(1) != Some(']') && self.peek_at(1).is_some()
            {
                self.bump(); // '-'
                let hi = match self.peek() {
                    Some('\\') => {
                        let es = self.i;
                        self.bump();
                        let e = match self.peek() {
                            Some(e) => e,
                            None => {
                                return Err(self.e1(
                                    "incomplete escape sequence, reached end of pattern prematurely",
                                    es,
                                ));
                            }
                        };
                        self.bump();
                        match e {
                            'n' => '\n',
                            'r' => '\r',
                            't' => '\t',
                            'x' | 'u' => {
                                let v = self.hex_escape(e)?;
                                match char::from_u32(v) {
                                    Some(ch) => ch,
                                    None => return Err(self.e1("invalid scalar value", es)),
                                }
                            }
                            other => other,
                        }
                    }
                    Some(ch) => {
                        self.bump();
                        ch
                    }
                    None => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            self.i,
                        ));
                    }
                };
                if hi < c {
                    return Err(self.err(
                        "invalid character class range, the start must be <= the end",
                        vec![(self.i - 2 - (1), self.i)],
                    ));
                }
                items.push(Item::Range(c, hi));
            } else {
                items.push(Item::Range(c, c));
            }
        }
        Ok(Node::Class(Class { items, neg }))
    }

    fn hex_escape(&mut self, which: char) -> R<u32> {
        let mut v: u32 = 0;
        if self.peek() == Some('{') {
            self.bump();
            let mut any = false;
            while let Some(ch) = self.peek() {
                if ch == '}' {
                    self.bump();
                    break;
                }
                if let Some(d) = ch.to_digit(16) {
                    v = v * 16 + d;
                    any = true;
                    self.bump();
                } else {
                    return Err(self.e1("invalid hexadecimal digit", self.i));
                }
            }
            if !any {
                return Err(self.e1("invalid hexadecimal digit", self.i));
            }
        } else {
            let n = if which == 'x' { 2 } else { 4 };
            for _ in 0..n {
                match self.peek() {
                    Some(ch) if ch.is_ascii_hexdigit() => {
                        v = v * 16 + ch.to_digit(16).unwrap();
                        self.bump();
                    }
                    _ => {
                        return Err(self.e1("invalid hexadecimal digit", self.i));
                    }
                }
            }
        }
        Ok(v)
    }
}

fn posix_by_name(n: &str) -> Option<Posix> {
    match n {
        "alnum" => Some(Posix::Alnum),
        "alpha" => Some(Posix::Alpha),
        "ascii" => Some(Posix::Ascii),
        "blank" => Some(Posix::Blank),
        "cntrl" => Some(Posix::Cntrl),
        "digit" => Some(Posix::Digit),
        "graph" => Some(Posix::Graph),
        "lower" => Some(Posix::Lower),
        "print" => Some(Posix::Print),
        "punct" => Some(Posix::Punct),
        "space" => Some(Posix::Space),
        "upper" => Some(Posix::Upper),
        "word" => Some(Posix::Word),
        "xdigit" => Some(Posix::Xdigit),
        _ => None,
    }
}

fn known_property(name: &str) -> bool {
    let n = name.trim().to_lowercase();
    const KNOWN: [&str; 40] = [
        "l", "lu", "ll", "lt", "lm", "lo", "lc", "n", "nd", "nl", "no", "p", "s", "z", "zs", "c",
        "cc", "m", "alpha", "alphabetic", "alnum", "digit", "space", "upper", "uppercase", "lower",
        "lowercase", "word", "blank", "cntrl", "print", "punct", "latin", "greek", "cyrillic",
        "han", "arabic", "hebrew", "hiragana", "katakana",
    ];
    if KNOWN.contains(&n.as_str()) {
        return true;
    }
    let up = name.trim().to_uppercase();
    const KNOWN2: [&str; 20] = [
        "UPPERCASE_LETTER",
        "LOWERCASE_LETTER",
        "DECIMAL_NUMBER",
        "SPACE_SEPARATOR",
        "LETTER",
        "NUMBER",
        "PUNCTUATION",
        "SYMBOL",
        "SEPARATOR",
        "CONTROL",
        "MARK",
        "TITLECASE_LETTER",
        "MODIFIER_LETTER",
        "OTHER_LETTER",
        "CASED_LETTER",
        "LETTER_NUMBER",
        "OTHER_NUMBER",
        "LINE_SEPARATOR",
        "PARAGRAPH_SEPARATOR",
        "FORMAT",
    ];
    KNOWN2.contains(&up.as_str())
}

// extra item for \p{..}
#[allow(non_camel_case_types)]
enum ItemX {}

// ---------------------------------------------------------------- matcher

struct Ctx {
    ci: bool,
}

enum Cont<'a> {
    Nil,
    Seq(&'a [Node], &'a Cont<'a>),
    Rep(&'a RepFrame<'a>),
}

struct RepFrame<'a> {
    seq: &'a [Node],
    rest: &'a [Node],
    cont: &'a Cont<'a>,
    min: u32,
    max: Option<u32>,
    greedy: bool,
    count: u32,
    start: usize,
}

struct Steps(u64);

impl Regex {
    pub fn is_match(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        let ctx = Ctx { ci: false };
        for start in 0..=chars.len() {
            let mut steps = Steps(0);
            if m_seq(&self.seq_of(), &chars[..], start, &Cont::Nil, &ctx, &mut steps) {
                return true;
            }
        }
        false
    }
    fn seq_of(&self) -> Vec<Node> {
        match &self.root {
            Node::Alt(b) => b.clone(),
            other => vec![other.clone()],
        }
    }
}

impl Regex {
    pub fn is_match_ci(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        let ctx = Ctx { ci: true };
        for start in 0..=chars.len() {
            let mut steps = Steps(0);
            if m_seq(&self.seq_of(), &chars[..], start, &Cont::Nil, &ctx, &mut steps) {
                return true;
            }
        }
        false
    }
}

fn m_seq(
    nodes: &[Node],
    text: &[char],
    pos: usize,
    cont: &Cont,
    ctx: &Ctx,
    steps: &mut Steps,
) -> bool {
    if steps.0 > 8_000_000 {
        return false;
    }
    steps.0 += 1;
    if nodes.is_empty() {
        match cont {
            Cont::Nil => true,
            Cont::Seq(rest, tail) => m_seq(rest, text, pos, tail, ctx, steps),
            Cont::Rep(frame) => {
                if pos == frame.start && frame.count >= frame.min {
                    return m_seq(frame.rest, text, pos, frame.cont, ctx, steps);
                }
                let f2 = RepFrame {
                    seq: frame.seq,
                    rest: frame.rest,
                    cont: frame.cont,
                    min: frame.min,
                    max: frame.max,
                    greedy: frame.greedy,
                    count: frame.count + 1,
                    start: pos,
                };
                rep_match(&f2, text, pos, ctx, steps)
            }
        }
    } else {
        let (first, rest) = nodes.split_first().unwrap();
        m_node(first, rest, text, pos, cont, ctx, steps)
    }
}

fn rep_match(frame: &RepFrame, text: &[char], pos: usize, ctx: &Ctx, steps: &mut Steps) -> bool {
    let can_more = frame.max.map_or(true, |m| frame.count < m);
    if frame.greedy {
        if can_more {
            let c = Cont::Rep(frame);
            if m_seq(frame.seq, text, pos, &c, ctx, steps) {
                return true;
            }
        }
        if frame.count >= frame.min {
            return m_seq(frame.rest, text, pos, frame.cont, ctx, steps);
        }
        false
    } else {
        if frame.count >= frame.min && m_seq(frame.rest, text, pos, frame.cont, ctx, steps) {
            return true;
        }
        if can_more {
            let c = Cont::Rep(frame);
            if m_seq(frame.seq, text, pos, &c, ctx, steps) {
                return true;
            }
        }
        false
    }
}

fn m_node(
    node: &Node,
    rest: &[Node],
    text: &[char],
    pos: usize,
    cont: &Cont,
    ctx: &Ctx,
    steps: &mut Steps,
) -> bool {
    match node {
        Node::Lit(c) => {
            if pos < text.len() && (text[pos] == *c || (ctx.ci && ci_eq(text[pos], *c))) {
                m_seq(rest, text, pos + 1, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::Any => {
            if pos < text.len() {
                m_seq(rest, text, pos + 1, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::Class(cl) => {
            if pos < text.len() && cl.matches(text[pos], ctx.ci) {
                m_seq(rest, text, pos + 1, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::StartLine => {
            if pos == 0 {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::EndLine => {
            if pos == text.len() {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::StartText => {
            if pos == 0 {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::EndText => {
            if pos == text.len() {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::WordB => {
            if at_word_boundary(text, pos) {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::NotWordB => {
            if !at_word_boundary(text, pos) {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::Group(seq) => {
            let c = Cont::Seq(rest, cont);
            m_seq(seq, text, pos, &c, ctx, steps)
        }
        Node::Alt(branches) => {
            let c = Cont::Seq(rest, cont);
            for b in branches.iter() {
                if m_seq(b, text, pos, &c, ctx, steps) {
                    return true;
                }
            }
            false
        }
        Node::Rep {
            seq,
            min,
            max,
            greedy,
        } => {
            let frame = RepFrame {
                seq,
                rest,
                cont,
                min: *min,
                max: *max,
                greedy: *greedy,
                count: 0,
                start: pos,
            };
            rep_match(&frame, text, pos, ctx, steps)
        }
    }
}

fn at_word_boundary(text: &[char], pos: usize) -> bool {
    let before = if pos == 0 { None } else { Some(text[pos - 1]) };
    let after = text.get(pos).copied();
    let b = before.map_or(false, is_word);
    let a = after.map_or(false, is_word);
    b != a
}

pub fn compile(pat: &str) -> Result<Regex, RegexError> {
    let chars: Vec<char> = pat.chars().collect();
