// A small regular expression engine, API-compatible (for the subset we need)
// with the `regex` crate: compile from a pattern, then `is_match` on a line.
//
// Supported syntax:
//   literals, `.`, `[...]` (with ranges, negation, escapes, POSIX classes and
//   nested classes), `\d \D \w \W \s \S \b \B`, anchors `^ $ \A \z \Z`,
//   groups `( )` `(?: )` `(?P<name> )`, inline flags `(?i)`, `(?i:...)`,
//   alternation `|`, repetition `* + ? {n} {n,} {n,m}` with optional laziness,
//   escapes `\n \t \r \f \v \a \0 \xNN \x{...} \uNNNN \\ \. ...`,
//   unicode properties `\p{..}` / `\pN` / `\P{..}`.

#[derive(Clone, Copy, PartialEq)]
pub enum Posix {
    Alnum,
    Alpha,
    Ascii,
    Blank,
    Cntrl,
    Digit,
    Graph,
    Lower,
    Print,
    Punct,
    Space,
    Upper,
    Word,
    Xdigit,
}

#[derive(Clone)]
pub enum Item {
    Range(char, char),
    Posix(Posix),
    Class(Class),
}

#[derive(Clone)]
pub struct Class {
    pub items: Vec<Item>,
    pub neg: bool,
}

#[derive(Clone)]
pub enum Node {
    Lit(char),
    Any,
    Class(Class),
    StartLine,
    EndLine,
    StartText,
    EndText,
    WordB,
    NotWordB,
    Group(Vec<Node>),
    Alt(Vec<Vec<Node>>),
    Rep {
        seq: Vec<Node>,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    },
}

pub struct RegexError {
    pub pattern: String,
    pub spans: Vec<(usize, usize)>,
    pub msg: String,
}

impl std::fmt::Display for RegexError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        let mut line = String::new();
        let mut idx = 0usize;
        let mut spans = self.spans.clone();
        spans.sort();
        for (s, e) in spans.iter() {
            if *s > idx {
                for _ in idx..*s {
                    line.push(' ');
                }
            }
            let width = if e > s { e - s } else { 1 };
            for _ in 0..width {
                line.push('^');
            }
            idx = *s + width;
        }
        write!(
            f,
            "regex parse error:\n    {}\n    {}\nerror: {}",
            self.pattern, line, self.msg
        )
    }
}

pub struct Regex {
    root: Node,
}

// ---------------------------------------------------------------- properties

fn posix_match(p: Posix, c: char) -> bool {
    match p {
        Posix::Alnum => c.is_alphanumeric(),
        Posix::Alpha => c.is_alphabetic(),
        Posix::Ascii => c.is_ascii(),
        Posix::Blank => c == ' ' || c == '\t',
        Posix::Cntrl => c.is_control(),
        Posix::Digit => c.is_numeric(),
        Posix::Graph => c.is_ascii_graphic() || (!c.is_whitespace() && !c.is_control() && !c.is_ascii()),
        Posix::Lower => c.is_lowercase(),
        Posix::Print => !c.is_control(),
        Posix::Punct => c.is_ascii_punctuation()
            || (!c.is_alphanumeric() && !c.is_whitespace() && !c.is_control()),
        Posix::Space => c.is_whitespace(),
        Posix::Upper => c.is_uppercase(),
        Posix::Word => c.is_alphanumeric() || c == '_',
        Posix::Xdigit => c.is_ascii_hexdigit(),
    }
}

fn prop_match(name: &str, c: char) -> bool {
    // single letter and two letter general categories plus a handful of names
    let n = name.trim();
    let up = n.to_uppercase();
    match up.as_str() {
        "L" | "LETTER" => c.is_alphabetic(),
        "LU" | "UPPERCASE_LETTER" => c.is_uppercase(),
        "LL" | "LOWERCASE_LETTER" => c.is_lowercase(),
        "LT" => c.is_uppercase(),
        "LM" | "LO" | "LC" => c.is_alphabetic(),
        "N" | "NUMBER" => c.is_numeric(),
        "ND" | "DECIMAL_NUMBER" => c.is_numeric(),
        "NL" | "NO" => c.is_numeric(),
        "P" | "PUNCTUATION" => !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control(),
        "S" | "SYMBOL" => !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control(),
        "Z" | "ZS" | "SEPARATOR" | "SPACE_SEPARATOR" => c.is_whitespace() && !c.is_control(),
        "C" | "CC" | "CONTROL" => c.is_control(),
        "M" | "MARK" => false,
        "ALPHA" | "ALPHABETIC" => c.is_alphabetic(),
        "ALNUM" => c.is_alphanumeric(),
        "DIGIT" => c.is_numeric(),
        "SPACE" => c.is_whitespace(),
        "UPPER" | "UPPERCASE" => c.is_uppercase(),
        "LOWER" | "LOWERCASE" => c.is_lowercase(),
        "WORD" => c.is_alphanumeric() || c == '_',
        "BLANK" => c == ' ' || c == '\t',
        "CNTRL" => c.is_control(),
        "PRINT" => !c.is_control(),
        "PUNCT" => !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control(),
        "GRAPHEMES" | "ANY" => true,
        _ => {
            // scripts and other names we cannot table: accept letters
            let l = n.to_lowercase();
            match l.as_str() {
                "latin" => c.is_alphabetic(),
                "greek" => c.is_alphabetic(),
                "cyrillic" => c.is_alphabetic(),
                "han" => c.is_alphabetic(),
                "hiragana" => c.is_alphabetic(),
                "katakana" => c.is_alphabetic(),
                "arabic" => c.is_alphabetic(),
                "hebrew" => c.is_alphabetic(),
                "ascii" => c.is_ascii(),
                "ascii_alphabetic" => c.is_ascii_alphabetic(),
                "ascii_alphanumeric" => c.is_ascii_alphanumeric(),
                "ascii_digit" => c.is_ascii_digit(),
                "ascii_lowercase" => c.is_ascii_lowercase(),
                "ascii_uppercase" => c.is_ascii_uppercase(),
                "ascii_punctuation" => c.is_ascii_punctuation(),
                "ascii_whitespace" => c.is_ascii_whitespace(),
                "ascii_graphic" => c.is_ascii_graphic(),
                "ascii_hexdigit" => c.is_ascii_hexdigit(),
                "ascii_control" => c.is_ascii_control(),
                _ => false,
            }
        }
    }
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

impl Class {
    fn raw_match(&self, c: char) -> bool {
        let mut hit = false;
        for it in self.items.iter() {
            let m = match it {
                Item::Range(a, b) => c >= *a && c <= *b,
                Item::Posix(p) => posix_match(*p, c),
                Item::Class(cl) => cl.raw_match(c),
            };
            if m {
                hit = true;
                break;
            }
        }
        if self.neg {
            !hit
        } else {
            hit
        }
    }
    fn matches(&self, c: char, ci: bool) -> bool {
        if self.raw_match(c) {
            return true;
        }
        if ci {
            for alt in case_variants(c) {
                if alt != c && self.raw_match(alt) {
                    return true;
                }
            }
        }
        false
    }
}

fn case_variants(c: char) -> Vec<char> {
    let mut v = Vec::new();
    for ch in c.to_lowercase() {
        v.push(ch);
    }
    for ch in c.to_uppercase() {
        v.push(ch);
    }
    if c.is_ascii_alphabetic() {
        v.push(c.to_ascii_uppercase());
        v.push(c.to_ascii_lowercase());
    }
    v
}

fn ci_eq(a: char, b: char) -> bool {
    if a == b {
        return true;
    }
    let mut la = a.to_lowercase();
    let mut lb = b.to_lowercase();
    loop {
        match (la.next(), lb.next()) {
            (None, None) => return true,
            (Some(x), Some(y)) => {
                if x != y {
                    // try simple ascii case
                    return a.to_ascii_lowercase() == b.to_ascii_lowercase()
                        && a.to_ascii_uppercase() == b.to_ascii_uppercase();
                }
            }
            _ => return false,
        }
    }
}

// ---------------------------------------------------------------- parser

struct Flags {
    ci: bool,
    swap: bool,
    x: bool,
}

impl Flags {
    fn new() -> Flags {
        Flags {
            ci: false,
            swap: false,
            x: false,
        }
    }
}

struct Parser {
    pat: String,
    c: Vec<char>,
    i: usize,
    flags: Flags,
    names: Vec<String>,
    depth: usize,
}

type R<T> = Result<T, RegexError>;

impl Parser {
    fn err(&self, msg: &str, spans: Vec<(usize, usize)>) -> RegexError {
        RegexError {
            pattern: self.pat.clone(),
            spans,
            msg: msg.to_string(),
        }
    }
    fn e1(&self, msg: &str, s: usize) -> RegexError {
        self.err(msg, vec![(s, s + 1)])
    }
    fn peek(&self) -> Option<char> {
        self.c.get(self.i).copied()
    }
    fn peek_at(&self, k: usize) -> Option<char> {
        self.c.get(self.i + k).copied()
    }
    fn bump(&mut self) {
        self.i += 1;
    }
    fn skip_x(&mut self) {
        if !self.flags.x {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.bump();
                }
                Some('#') => {
                    while let Some(c) = self.peek() {
                        self.bump();
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    fn parse(&mut self) -> R<Node> {
        let branches = self.alt()?;
        if let Some(p) = self.peek() {
            // leftover ')' at the top level
            return Err(self.e1("unopened group", self.i));
        }
        Ok(Node::Alt(branches))
    }

    fn alt(&mut self) -> R<Vec<Vec<Node>>> {
        let mut branches = Vec::new();
        loop {
            self.skip_x();
            branches.push(self.seq()?);
            self.skip_x();
            if self.peek() == Some('|') {
                self.bump();
                continue;
            }
            break;
        }
        Ok(branches)
    }

    fn seq(&mut self) -> R<Vec<Node>> {
        let mut out: Vec<Node> = Vec::new();
        loop {
            self.skip_x();
            match self.peek() {
                None | Some('|') | Some(')') => break,
                Some('*') | Some('+') | Some('?') | Some('{') => {
                    let p = self.i;
                    return Err(self.e1("repetition operator missing expression", p));
                }
                _ => {}
            }
            let atom = self.atom()?;
            let node = self.quantifiers(atom)?;
            out.push(node);
        }
        Ok(out)
    }

    fn quantifiers(&mut self, atom: Node) -> R<Node> {
        let mut node = atom;
        loop {
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.bump();
                    (0u32, None)
                }
                Some('+') => {
                    self.bump();
                    (1u32, None)
                }
                Some('?') => {
                    self.bump();
                    (0u32, Some(1u32))
                }
                Some('{') => match self.counted()? {
                    Some((a, b)) => (a, b),
                    None => break,
                },
                _ => break,
            };
            let mut greedy = !self.flags.swap;
            if self.peek() == Some('?') {
                self.bump();
                greedy = !greedy;
            }
            node = Node::Rep {
                seq: vec![node],
                min,
                max,
                greedy,
            };
        }
        Ok(node)
    }

    // returns None when the brace is meant literally
    fn counted(&mut self) -> R<Option<(u32, Option<u32>)>> {
        let open = self.i;
        self.bump(); // consume '{'
        let first = match self.peek() {
            Some(c) if c.is_ascii_digit() => {
                let mut n: u64 = 0;
                let mut any = false;
                while let Some(c) = self.peek() {
                    if let Some(d) = c.to_digit(10) {
                        n = n * 10 + d as u64;
                        any = true;
                        self.bump();
                    } else {
                        break;
                    }
                }
                if !any {
                    return Err(self.e1("repetition quantifier expects a valid decimal", self.i));
                }
                if n > 100000 {
                    return Err(self.e1("repetition quantifier expects a valid decimal", open + 1));
                }
                n
            }
            Some(_) => {
                return Err(self.e1("repetition quantifier expects a valid decimal", self.i));
            }
            None => {
                return Err(self.err(
                    "unclosed counted repetition",
                    vec![(open, self.i)],
                ));
            }
        };
        let mut second: Option<u64> = None;
        if self.peek() == Some(',') {
            self.bump();
            if self.peek() == Some('}') {
                second = None;
            } else {
                let mut n: u64 = 0;
                let mut any = false;
                while let Some(c) = self.peek() {
                    if let Some(d) = c.to_digit(10) {
                        n = n * 10 + d as u64;
                        any = true;
                        self.bump();
                    } else {
                        break;
                    }
                }
                if !any {
                    return Err(self.e1("repetition quantifier expects a valid decimal", self.i));
                }
                second = Some(n);
            }
        }
        if self.peek() != Some('}') {
            return Err(self.err("unclosed counted repetition", vec![(open, self.i)]));
        }
        self.bump(); // consume '}'
        // laziness marker is consumed by the caller before the range check
        if let Some(hi) = second {
            if hi < first {
                let mut end = self.i;
                if self.peek() == Some('?') {
                    end += 1;
                }
                return Err(self.err(
                    "invalid repetition count range, the start must be <= the end",
                    vec![(open, end)],
                ));
            }
        }
        Ok(Some((
            first as u32,
            second.map(|v| v as u32),
        )))
    }

    fn atom(&mut self) -> R<Node> {
        let c = self.peek().unwrap();
        match c {
            '.' => {
                self.bump();
                Ok(Node::Any)
            }
            '^' => {
                self.bump();
                Ok(Node::StartLine)
            }
            '$' => {
                self.bump();
                Ok(Node::EndLine)
            }
            '[' => self.class(),
            '(' => self.group(),
            '\\' => self.escape(),
            _ => {
                self.bump();
                Ok(Node::Lit(c))
            }
        }
    }

    fn group(&mut self) -> R<Node> {
        let open = self.i;
        self.bump(); // '('
        let saved_flags = Flags {
            ci: self.flags.ci,
            swap: self.flags.swap,
            x: self.flags.x,
        };
        let mut named: Option<(String, usize)> = None;
        let mut reset_at_end = false;
        if self.peek() == Some('?') {
            self.bump();
            match self.peek() {
                Some(':') => {
                    self.bump();
                }
                Some('P') => {
                    let p = self.i;
                    self.bump();
                    if self.peek() == Some('<') {
                        self.bump();
                        let name_start = self.i;
                        let mut name = String::new();
                        loop {
                            match self.peek() {
                                Some('>') => {
                                    self.bump();
                                    break;
                                }
                                Some(c) if c.is_alphanumeric() || c == '_' => {
                                    name.push(c);
                                    self.bump();
                                }
                                Some(_) => {
                                    return Err(self.e1(
                                        "unrecognized syntax in capture group name",
                                        self.i,
                                    ));
                                }
                                None => {
                                    return Err(self.e1("unclosed capture group name", self.i));
                                }
                            }
                        }
                        if name.is_empty() {
                            return Err(self.e1("empty capture group name", name_start));
                        }
                        if self.names.iter().any(|n| *n == name) {
                            let first = self
                                .names
                                .iter()
                                .position(|n| *n == name)
                                .unwrap();
                            let _ = first;
                            return Err(self.err(
                                "duplicate capture group name",
                                vec![(p + 2, p + 3), (name_start, self.i)],
                            ));
                        }
                        self.names.push(name.clone());
                        named = Some((name, p));
                    } else {
                        return Err(self.e1("unrecognized flag", p));
                    }
                }
                Some(c) if "imsxUu-".contains(c) => {
                    let mut neg = false;
                    let mut seen: Vec<char> = Vec::new();
                    let mut dup_spans: Vec<(usize, usize)> = Vec::new();
                    loop {
                        match self.peek() {
                            None => {
                                return Err(self.e1("expected flag but got end of regex", self.i));
                            }
                            Some('-') => {
                                if neg {
                                    return Err(self.e1("duplicate flag", self.i));
                                }
                                neg = true;
                                self.bump();
                            }
                            Some(f) if "imsxUu".contains(f) => {
                                if seen.contains(&f) {
                                    let first = seen.iter().position(|x| *x == f).unwrap();
                                    let _ = first;
                                    // report both positions
                                    let first_pos = 0usize; // resolved below
                                    let _ = first_pos;
                                    dup_spans.push((self.i, self.i + 1));
                                    if dup_spans.len() == 2 {
                                        let mut spans = dup_spans.clone();
                                        spans.sort();
                                        return Err(self.err("duplicate flag", spans));
                                    }
                                } else {
                                    seen.push(f);
                                    match f {
                                        'i' => self.flags.ci = !neg,
                                        'U' => self.flags.swap = !neg,
                                        'x' => self.flags.x = !neg,
                                        _ => {}
                                    }
                                }
                                self.bump();
                            }
                            Some(':') => {
                                self.bump();
                                let branches = self.alt()?;
                                if self.peek() != Some(')') {
                                    return Err(self.e1("unclosed group", open));
                                }
                                self.bump();
                                self.flags = saved_flags;
                                return Ok(Node::Alt(branches));
                            }
                            Some(_) => {
                                let p = self.i;
                                let _ = p;
                                return Err(self.e1("unrecognized flag", self.i));
                            }
                        }
                    }
                }
                Some(_) => {
                    let p = self.i;
                    return Err(self.e1("unrecognized flag", p));
                }
                None => {
                    return Err(self.e1("unclosed group", open));
                }
            }
        }
        let branches = self.alt()?;
        if self.peek() != Some(')') {
            return Err(self.e1("unclosed group", open));
        }
        self.bump();
        if reset_at_end {
            self.flags = saved_flags;
        }
        if named.is_some() {
            // fallthrough
        }
        let _ = &saved_flags;
        if branches.len() == 1 {
            Ok(Node::Group(branches.pop().unwrap()))
        } else {
            Ok(Node::Group(vec![Node::Alt(branches)]))
        }
    }

    fn escape(&mut self) -> R<Node> {
        let start = self.i;
        self.bump(); // '\\'
        let c = match self.peek() {
            Some(c) => c,
            None => {
                return Err(self.e1(
                    "incomplete escape sequence, reached end of pattern prematurely",
                    start,
                ));
            }
        };
        self.bump();
        match c {
            'd' | 'D' | 'w' | 'W' | 's' | 'S' | 'p' | 'P' => {
                if c == 'd' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Digit)],
                        neg: false,
                    }));
                }
                if c == 'D' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Digit)],
                        neg: true,
                    }));
                }
                if c == 'w' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Word)],
                        neg: false,
                    }));
                }
                if c == 'W' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Word)],
                        neg: true,
                    }));
                }
                if c == 's' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Space)],
                        neg: false,
                    }));
                }
                if c == 'S' {
                    return Ok(Node::Class(Class {
                        items: vec![Item::Posix(Posix::Space)],
                        neg: true,
                    }));
                }
                // unicode property
                let name: String;
                let mut end = self.i;
                if self.peek() == Some('{') {
                    self.bump();
                    let mut n = String::new();
                    loop {
                        match self.peek() {
                            Some('}') => {
                                self.bump();
                                break;
                            }
                            Some(ch) => {
                                n.push(ch);
                                self.bump();
                            }
                            None => {
                                return Err(self.e1(
                                    "unclosed counted repetition",
                                    start,
                                ));
                            }
                        }
                    }
                    name = n;
                    end = self.i;
                } else {
                    match self.peek() {
                        Some(ch) if ch.is_ascii_alphabetic() => {
                            name = ch.to_string();
                            self.bump();
                            end = self.i;
                        }
                        _ => {
                            return Err(self.e1(
                                "incomplete escape sequence, reached end of pattern prematurely",
                                end,
                            ));
                        }
                    }
                }
                let neg = c == 'P';
                if !prop_match(&name, 'a') && !prop_match(&name, '0') && !prop_match(&name, ' ') {
                    if !known_property(&name) {
                        return Err(self.err(
                            "Unicode property not found",
                            vec![(start, end)],
                        ));
                    }
                }
                Ok(Node::Class(Class {
                    items: vec![Item::Prop(name)],
                    neg,
                }))
            }
            'b' => Ok(Node::WordB),
            'B' => Ok(Node::NotWordB),
            'A' => Ok(Node::StartText),
            'z' => Ok(Node::EndText),
            'Z' => Ok(Node::EndText),
            'n' => Ok(Node::Lit('\n')),
            'r' => Ok(Node::Lit('\r')),
            't' => Ok(Node::Lit('\t')),
            'f' => Ok(Node::Lit('\u{c}')),
            'v' => Ok(Node::Lit('\u{b}')),
            'a' => Ok(Node::Lit('\u{7}')),
            '0' => Ok(Node::Lit('\0')),
            'x' => {
                let mut v: u32 = 0;
                if self.peek() == Some('{') {
                    self.bump();
                    let mut any = false;
                    while let Some(ch) = self.peek() {
                        if ch == '}' {
                            self.bump();
                            break;
                        }
                        if let Some(d) = ch.to_digit(16) {
                            v = v * 16 + d;
                            any = true;
                            self.bump();
                        } else {
                            return Err(self.e1("invalid hexadecimal digit", self.i));
                        }
                    }
                    if !any {
                        return Err(self.e1("invalid hexadecimal digit", self.i));
                    }
                } else {
                    for _ in 0..2 {
                        match self.peek() {
                            Some(ch) if ch.is_ascii_hexdigit() => {
                                v = v * 16 + ch.to_digit(16).unwrap();
                                self.bump();
                            }
                            _ => {
                                return Err(self.e1(
                                    "incomplete escape sequence, reached end of pattern prematurely",
                                    self.i,
                                ));
                            }
                        }
                    }
                }
                match char::from_u32(v) {
                    Some(ch) => Ok(Node::Lit(ch)),
                    None => Err(self.e1("invalid scalar value", start)),
                }
            }
            'u' => {
                let mut v: u32 = 0;
                for _ in 0..4 {
                    match self.peek() {
                        Some(ch) if ch.is_ascii_hexdigit() => {
                            v = v * 16 + ch.to_digit(16).unwrap();
                            self.bump();
                        }
                        _ => {
                            return Err(self.e1("invalid hexadecimal digit", self.i));
                        }
                    }
                }
                match char::from_u32(v) {
                    Some(ch) => Ok(Node::Lit(ch)),
                    None => Err(self.e1("invalid scalar value", start)),
                }
            }
            '1'..='9' => Err(self.err(
                "backreferences are not supported",
                vec![(start, self.i)],
            )),
            _ => {
                if c.is_ascii_alphanumeric() {
                    return Err(self.err("unrecognized escape sequence", vec![(start, self.i)]));
                }
                Ok(Node::Lit(c))
            }
        }
    }

    fn class(&mut self) -> R<Node> {
        let open = self.i;
        self.bump(); // '['
        let mut neg = false;
        if self.peek() == Some('^') {
            neg = true;
            self.bump();
        }
        let mut items: Vec<Item> = Vec::new();
        let mut first = true;
        let mut consumed_close = false;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => {
                    let mut width = 1;
                    if neg {
                        width += 1;
                    }
                    if consumed_close {
                        width += 1;
                    }
                    return Err(self.err(
                        "unclosed character class",
                        vec![(open, open + width)],
                    ));
                }
            };
            if c == ']' && !first {
                self.bump();
                break;
            }
            if c == ']' && first {
                // literal ']' as the first item
                consumed_close = true;
                self.bump();
                items.push(Item::Range(']', ']'));
                first = false;
                continue;
            }
            first = false;
            if c == '[' {
                // posix class or nested class
                if self.peek_at(1) == Some(':') {
                    // find closing ":]"
                    let save = self.i;
                    let mut j = self.i + 2;
                    let mut negp = false;
                    if self.peek_at(2) == Some('^') {
                        negp = true;
                        j += 1;
                    }
                    let mut name = String::new();
                    let mut found = false;
                    while j < self.c.len() {
                        if self.c[j] == ':' && j + 1 < self.c.len() && self.c[j + 1] == ']' {
                            found = true;
                            break;
                        }
                        name.push(self.c[j]);
                        j += 1;
                    }
                    if found {
                        for k in self.i..=j + 1 {
                            let _ = k;
                        }
                        let p = match posix_by_name(&name) {
                            Some(p) => p,
                            None => {
                                return Err(self.err(
                                    "unrecognized POSIX character class",
                                    vec![(self.i, j + 2)],
                                ));
                            }
                        };
                        items.push(Item::Posix(p));
                        // rewind then advance properly
                        self.i = j + 2;
                        continue;
                    }
                    // not a posix class: nested class
                    self.i = save;
                }
                let nested = self.class()?;
                match nested {
                    Node::Class(cl) => items.push(Item::Class(cl)),
                    _ => {}
                }
                continue;
            }
            if c == '\\' {
                // escape inside class
                let es = self.i;
                self.bump();
                let e = match self.peek() {
                    Some(e) => e,
                    None => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            es,
                        ));
                    }
                };
                self.bump();
                match e {
                    'd' | 'D' | 'w' | 'W' | 's' | 'S' => {
                        let (p, n) = match e {
                            'd' => (Posix::Digit, false),
                            'D' => (Posix::Digit, true),
                            'w' => (Posix::Word, false),
                            'W' => (Posix::Word, true),
                            's' => (Posix::Space, false),
                            _ => (Posix::Space, true),
                        };
                        items.push(Item::Class(Class {
                            items: vec![Item::Posix(p)],
                            neg: n,
                        }));
                    }
                    'p' | 'P' => {
                        let mut name = String::new();
                        let mut end = self.i;
                        if self.peek() == Some('{') {
                            self.bump();
                            while let Some(ch) = self.peek() {
                                if ch == '}' {
                                    self.bump();
                                    break;
                                }
                                name.push(ch);
                                self.bump();
                            }
                            end = self.i;
                        } else if let Some(ch) = self.peek() {
                            name = ch.to_string();
                            self.bump();
                            end = self.i;
                        } else {
                            return Err(self.e1(
                                "incomplete escape sequence, reached end of pattern prematurely",
                                es,
                            ));
                        }
                        if !known_property(&name) {
                            return Err(self.err("Unicode property not found", vec![(es, end)]));
                        }
                        items.push(Item::PropName(name, e == 'P'));
                    }
                    'n' => items.push(Item::Range('\n', '\n')),
                    'r' => items.push(Item::Range('\r', '\r')),
                    't' => items.push(Item::Range('\t', '\t')),
                    'f' => items.push(Item::Range('\u{c}', '\u{c}')),
                    'v' => items.push(Item::Range('\u{b}', '\u{b}')),
                    'a' => items.push(Item::Range('\u{7}', '\u{7}')),
                    'b' => items.push(Item::Range('\u{8}', '\u{8}')),
                    '0' => items.push(Item::Range('\0', '\0')),
                    'x' | 'u' => {
                        let v = self.hex_escape(e)?;
                        match char::from_u32(v) {
                            Some(ch) => items.push(Item::Range(ch, ch)),
                            None => {
                                return Err(self.e1("invalid scalar value", es));
                            }
                        }
                    }
                    other => items.push(Item::Range(other, other)),
                }
                continue;
            }
            // plain char, possible range
            self.bump();
            if self.peek() == Some('-') && self.peek_at(1) != Some(']') && self.peek_at(1).is_some()
            {
                self.bump(); // '-'
                let hi = match self.peek() {
                    Some('\\') => {
                        let es = self.i;
                        self.bump();
                        let e = match self.peek() {
                            Some(e) => e,
                            None => {
                                return Err(self.e1(
                                    "incomplete escape sequence, reached end of pattern prematurely",
                                    es,
                                ));
                            }
                        };
                        self.bump();
                        match e {
                            'n' => '\n',
                            'r' => '\r',
                            't' => '\t',
                            'x' | 'u' => {
                                let v = self.hex_escape(e)?;
                                match char::from_u32(v) {
                                    Some(ch) => ch,
                                    None => return Err(self.e1("invalid scalar value", es)),
                                }
                            }
                            other => other,
                        }
                    }
                    Some(ch) => {
                        self.bump();
                        ch
                    }
                    None => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            self.i,
                        ));
                    }
                };
                if hi < c {
                    return Err(self.err(
                        "invalid character class range, the start must be <= the end",
                        vec![(self.i - 2 - (1), self.i)],
                    ));
                }
                items.push(Item::Range(c, hi));
            } else {
                items.push(Item::Range(c, c));
            }
        }
        Ok(Node::Class(Class { items, neg }))
    }

    fn hex_escape(&mut self, which: char) -> R<u32> {
        let mut v: u32 = 0;
        if self.peek() == Some('{') {
            self.bump();
            let mut any = false;
            while let Some(ch) = self.peek() {
                if ch == '}' {
                    self.bump();
                    break;
                }
                if let Some(d) = ch.to_digit(16) {
                    v = v * 16 + d;
                    any = true;
                    self.bump();
                } else {
                    return Err(self.e1("invalid hexadecimal digit", self.i));
                }
            }
            if !any {
                return Err(self.e1("invalid hexadecimal digit", self.i));
            }
        } else {
            let n = if which == 'x' { 2 } else { 4 };
            for _ in 0..n {
                match self.peek() {
                    Some(ch) if ch.is_ascii_hexdigit() => {
                        v = v * 16 + ch.to_digit(16).unwrap();
                        self.bump();
                    }
                    _ => {
                        return Err(self.e1("invalid hexadecimal digit", self.i));
                    }
                }
            }
        }
        Ok(v)
    }
}

fn posix_by_name(n: &str) -> Option<Posix> {
    match n {
        "alnum" => Some(Posix::Alnum),
        "alpha" => Some(Posix::Alpha),
        "ascii" => Some(Posix::Ascii),
        "blank" => Some(Posix::Blank),
        "cntrl" => Some(Posix::Cntrl),
        "digit" => Some(Posix::Digit),
        "graph" => Some(Posix::Graph),
        "lower" => Some(Posix::Lower),
        "print" => Some(Posix::Print),
        "punct" => Some(Posix::Punct),
        "space" => Some(Posix::Space),
        "upper" => Some(Posix::Upper),
        "word" => Some(Posix::Word),
        "xdigit" => Some(Posix::Xdigit),
        _ => None,
    }
}

fn known_property(name: &str) -> bool {
    let n = name.trim().to_lowercase();
    const KNOWN: [&str; 40] = [
        "l", "lu", "ll", "lt", "lm", "lo", "lc", "n", "nd", "nl", "no", "p", "s", "z", "zs", "c",
        "cc", "m", "alpha", "alphabetic", "alnum", "digit", "space", "upper", "uppercase", "lower",
        "lowercase", "word", "blank", "cntrl", "print", "punct", "latin", "greek", "cyrillic",
        "han", "arabic", "hebrew", "hiragana", "katakana",
    ];
    if KNOWN.contains(&n.as_str()) {
        return true;
    }
    let up = name.trim().to_uppercase();
    const KNOWN2: [&str; 20] = [
        "UPPERCASE_LETTER",
        "LOWERCASE_LETTER",
        "DECIMAL_NUMBER",
        "SPACE_SEPARATOR",
        "LETTER",
        "NUMBER",
        "PUNCTUATION",
        "SYMBOL",
        "SEPARATOR",
        "CONTROL",
        "MARK",
        "TITLECASE_LETTER",
        "MODIFIER_LETTER",
        "OTHER_LETTER",
        "CASED_LETTER",
        "LETTER_NUMBER",
        "OTHER_NUMBER",
        "LINE_SEPARATOR",
        "PARAGRAPH_SEPARATOR",
        "FORMAT",
    ];
    KNOWN2.contains(&up.as_str())
}

// extra item for \p{..}
#[allow(non_camel_case_types)]
enum ItemX {}

// ---------------------------------------------------------------- matcher

struct Ctx {
    ci: bool,
}

enum Cont<'a> {
    Nil,
    Seq(&'a [Node], &'a Cont<'a>),
    Rep(&'a RepFrame<'a>),
}

struct RepFrame<'a> {
    seq: &'a [Node],
    rest: &'a [Node],
    cont: &'a Cont<'a>,
    min: u32,
    max: Option<u32>,
    greedy: bool,
    count: u32,
    start: usize,
}

struct Steps(u64);

impl Regex {
    pub fn is_match(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        let ctx = Ctx { ci: false };
        for start in 0..=chars.len() {
            let mut steps = Steps(0);
            if m_seq(&self.seq_of(), &chars[..], start, &Cont::Nil, &ctx, &mut steps) {
                return true;
            }
        }
        false
    }
    fn seq_of(&self) -> Vec<Node> {
        match &self.root {
            Node::Alt(b) => b.clone(),
            other => vec![other.clone()],
        }
    }
}

impl Regex {
    pub fn is_match_ci(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        let ctx = Ctx { ci: true };
        for start in 0..=chars.len() {
            let mut steps = Steps(0);
            if m_seq(&self.seq_of(), &chars[..], start, &Cont::Nil, &ctx, &mut steps) {
                return true;
            }
        }
        false
    }
}

fn m_seq(
    nodes: &[Node],
    text: &[char],
    pos: usize,
    cont: &Cont,
    ctx: &Ctx,
    steps: &mut Steps,
) -> bool {
    if steps.0 > 8_000_000 {
        return false;
    }
    steps.0 += 1;
    if nodes.is_empty() {
        match cont {
            Cont::Nil => true,
            Cont::Seq(rest, tail) => m_seq(rest, text, pos, tail, ctx, steps),
            Cont::Rep(frame) => {
                if pos == frame.start && frame.count >= frame.min {
                    return m_seq(frame.rest, text, pos, frame.cont, ctx, steps);
                }
                let f2 = RepFrame {
                    seq: frame.seq,
                    rest: frame.rest,
                    cont: frame.cont,
                    min: frame.min,
                    max: frame.max,
                    greedy: frame.greedy,
                    count: frame.count + 1,
                    start: pos,
                };
                rep_match(&f2, text, pos, ctx, steps)
            }
        }
    } else {
