// A small regular expression engine covering the subset of the `regex` crate
// syntax that matters for this program: compile a pattern, then test whether
// any line matches.
//
//   literals, `.`, `[...]` (ranges, negation, escapes, POSIX classes, nested
//   classes), `\d \D \w \W \s \S \b \B`, anchors `^ $ \A \z \Z`,
//   groups `(...)` `(?:...)` `(?P<name>...)`, inline flags `(?i)` `(?i:...)`,
//   alternation `|`, repetition `* + ? {n} {n,} {n,m}` (optionally lazy),
//   escapes `\n \t \r \f \v \a \0 \xNN \x{...} \uNNNN \\ \. ...`,
//   unicode properties `\p{..}` `\pN` `\P{..}`.

#[derive(Clone, Copy, PartialEq)]
pub enum Posix {
    Alnum,
    Alpha,
    Ascii,
    Blank,
    Cntrl,
    Digit,
    Graph,
    Lower,
    Print,
    Punct,
    Space,
    Upper,
    Word,
    Xdigit,
}

#[derive(Clone)]
pub enum Item {
    Range(char, char),
    Posix(Posix),
    Class(Class),
    Prop(String, bool),
}

#[derive(Clone)]
pub struct Class {
    pub items: Vec<Item>,
    pub neg: bool,
}

#[derive(Clone)]
pub enum Node {
    Lit(char),
    Any,
    Class(Class),
    StartLine,
    EndLine,
    StartText,
    EndText,
    WordB,
    NotWordB,
    Group(Vec<Node>),
    Alt(Vec<Vec<Node>>),
    Rep {
        seq: Vec<Node>,
        min: u32,
        max: Option<u32>,
        greedy: bool,
    },
}

pub struct RegexError {
    pub pattern: String,
    pub spans: Vec<(usize, usize)>,
    pub msg: String,
}

impl std::fmt::Display for RegexError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        let mut line = String::new();
        let mut idx = 0usize;
        let mut spans = self.spans.clone();
        spans.sort();
        for (s, e) in spans.iter() {
            if *s > idx {
                for _ in idx..*s {
                    line.push(' ');
                }
            }
            let width = if e > s { e - s } else { 1 };
            for _ in 0..width {
                line.push('^');
            }
            idx = *s + width;
        }
        write!(
            f,
            "regex parse error:\n    {}\n    {}\nerror: {}",
            self.pattern, line, self.msg
        )
    }
}

pub struct Regex {
    root: Node,
    ci: bool,
}

// ---------------------------------------------------------------- predicates

fn posix_match(p: Posix, c: char) -> bool {
    match p {
        Posix::Alnum => c.is_alphanumeric(),
        Posix::Alpha => c.is_alphabetic(),
        Posix::Ascii => c.is_ascii(),
        Posix::Blank => c == ' ' || c == '\t',
        Posix::Cntrl => c.is_control(),
        Posix::Digit => c.is_numeric(),
        Posix::Graph => c.is_ascii_graphic() || (c > '\u{7f}' && !c.is_whitespace() && !c.is_control()),
        Posix::Lower => c.is_lowercase(),
        Posix::Print => !c.is_control(),
        Posix::Punct => {
            c.is_ascii_punctuation()
                || (c > '\u{7f}' && !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control())
        }
        Posix::Space => c.is_whitespace(),
        Posix::Upper => c.is_uppercase(),
        Posix::Word => c.is_alphanumeric() || c == '_',
        Posix::Xdigit => c.is_ascii_hexdigit(),
    }
}

fn prop_match(name: &str, c: char) -> bool {
    let n = name.trim().to_lowercase();
    match n.as_str() {
        "l" | "letter" => c.is_alphabetic(),
        "lu" | "uppercase_letter" | "uppercase" => c.is_uppercase(),
        "ll" | "lowercase_letter" | "lowercase" => c.is_lowercase(),
        "lt" | "titlecase_letter" => c.is_uppercase(),
        "lm" | "lo" | "lc" | "cased_letter" | "modifier_letter" | "other_letter" => c.is_alphabetic(),
        "n" | "number" => c.is_numeric(),
        "nd" | "decimal_number" | "digit" => c.is_numeric(),
        "nl" | "letter_number" | "no" | "other_number" => c.is_numeric(),
        "p" | "punctuation" | "punct" => {
            !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control()
        }
        "s" | "symbol" => !c.is_alphanumeric() && !c.is_whitespace() && !c.is_control(),
        "z" | "zs" | "separator" | "space_separator" | "space" => {
            c.is_whitespace() && !c.is_control()
        }
        "c" | "cc" | "control" | "cntrl" => c.is_control(),
        "m" | "mark" => false,
        "alpha" | "alphabetic" => c.is_alphabetic(),
        "alnum" => c.is_alphanumeric(),
        "upper" => c.is_uppercase(),
        "lower" => c.is_lowercase(),
        "word" => c.is_alphanumeric() || c == '_',
        "blank" => c == ' ' || c == '\t',
        "print" => !c.is_control(),
        "any" | "graphemes" => true,
        "ascii" => c.is_ascii(),
        "ascii_alphabetic" => c.is_ascii_alphabetic(),
        "ascii_alphanumeric" => c.is_ascii_alphanumeric(),
        "ascii_digit" | "ascii_dec_digit" | "ascii_dec_digit_number" => c.is_ascii_digit(),
        "ascii_lowercase" => c.is_ascii_lowercase(),
        "ascii_uppercase" => c.is_ascii_uppercase(),
        "ascii_punctuation" => c.is_ascii_punctuation(),
        "ascii_whitespace" => c.is_ascii_whitespace(),
        "ascii_graphic" | "ascii_graph" => c.is_ascii_graphic(),
        "ascii_hexdigit" | "ascii_hex_digit" => c.is_ascii_hexdigit(),
        "ascii_control" => c.is_ascii_control(),
        _ => {
            // scripts: fall back to a coarse letter test
            matches!(
                n.as_str(),
                "latin"
                    | "greek"
                    | "cyrillic"
                    | "han"
                    | "hiragana"
                    | "katakana"
                    | "arabic"
                    | "hebrew"
                    | "thai"
                    | "hangul"
                    | "armenian"
                    | "georgian"
                    | "bengali"
                    | "devanagari"
                    | "tibetan"
                    | "khmer"
                    | "lao"
                    | "myanmar"
                    | "sinhala"
                    | "telugu"
                    | "kanna"
                    | "common"
                    | "inherited"
                    | "unknown"
            ) && c.is_alphabetic()
        }
    }
}

fn known_property(name: &str) -> bool {
    let n = name.trim().to_lowercase();
    const KNOWN: [&str; 45] = [
        "l", "lu", "ll", "lt", "lm", "lo", "lc", "n", "nd", "nl", "no", "p", "s", "z", "zs", "c",
        "cc", "m", "alpha", "alphabetic", "alnum", "digit", "space", "upper", "uppercase", "lower",
        "lowercase", "word", "blank", "cntrl", "print", "punct", "latin", "greek", "cyrillic",
        "han", "arabic", "hebrew", "hiragana", "katakana", "letter", "number", "punctuation",
        "symbol", "separator",
    ];
    if KNOWN.contains(&n.as_str()) {
        return true;
    }
    let up = name.trim().to_uppercase();
    const KNOWN2: [&str; 18] = [
        "UPPERCASE_LETTER",
        "LOWERCASE_LETTER",
        "DECIMAL_NUMBER",
        "SPACE_SEPARATOR",
        "LETTER",
        "NUMBER",
        "PUNCTUATION",
        "SYMBOL",
        "SEPARATOR",
        "CONTROL",
        "MARK",
        "TITLECASE_LETTER",
        "MODIFIER_LETTER",
        "OTHER_LETTER",
        "CASED_LETTER",
        "LETTER_NUMBER",
        "OTHER_NUMBER",
        "GRAPHEMES",
    ];
    KNOWN2.contains(&up.as_str())
}

fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn case_variants(c: char) -> Vec<char> {
    let mut v = Vec::new();
    for ch in c.to_lowercase() {
        v.push(ch);
    }
    for ch in c.to_uppercase() {
        v.push(ch);
    }
    v
}

fn ci_eq(a: char, b: char) -> bool {
    if a == b {
        return true;
    }
    let mut la = a.to_lowercase();
    let mut lb = b.to_lowercase();
    loop {
        match (la.next(), lb.next()) {
            (None, None) => return true,
            (Some(x), Some(y)) => {
                if x != y {
                    return false;
                }
            }
            _ => return false,
        }
    }
}

impl Class {
    fn raw_match(&self, c: char) -> bool {
        let mut hit = false;
        for it in self.items.iter() {
            let m = match it {
                Item::Range(a, b) => c >= *a && c <= *b,
                Item::Posix(p) => posix_match(*p, c),
                Item::Class(cl) => cl.raw_match(c),
                Item::Prop(name, neg) => prop_match(name, c) != *neg,
            };
            if m {
                hit = true;
                break;
            }
        }
        if self.neg {
            !hit
        } else {
            hit
        }
    }
    fn matches(&self, c: char, ci: bool) -> bool {
        if self.raw_match(c) {
            return true;
        }
        if ci {
            for alt in case_variants(c) {
                if alt != c && self.raw_match(alt) {
                    return true;
                }
            }
        }
        false
    }
}

// ---------------------------------------------------------------- parser

#[derive(Clone, Copy)]
struct Flags {
    ci: bool,
    swap: bool,
    x: bool,
}

impl Flags {
    fn new() -> Flags {
        Flags {
            ci: false,
            swap: false,
            x: false,
        }
    }
}

struct Parser {
    pat: String,
    c: Vec<char>,
    i: usize,
    flags: Flags,
    names: Vec<(String, usize)>,
}

type R<T> = Result<T, RegexError>;

impl Parser {
    fn err(&self, msg: &str, spans: Vec<(usize, usize)>) -> RegexError {
        RegexError {
            pattern: self.pat.clone(),
            spans,
            msg: msg.to_string(),
        }
    }
    fn e1(&self, msg: &str, s: usize) -> RegexError {
        self.err(msg, vec![(s, s + 1)])
    }
    fn peek(&self) -> Option<char> {
        self.c.get(self.i).copied()
    }
    fn at(&self, k: usize) -> Option<char> {
        self.c.get(k).copied()
    }
    fn bump(&mut self) {
        self.i += 1;
    }
    fn skip_x(&mut self) {
        if !self.flags.x {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.bump();
                }
                Some('#') => {
                    while let Some(c) = self.peek() {
                        self.bump();
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    fn parse(&mut self) -> R<Node> {
        let branches = self.alt()?;
        if self.peek().is_some() {
            return Err(self.e1("unopened group", self.i));
        }
        Ok(Node::Alt(branches))
    }

    fn alt(&mut self) -> R<Vec<Vec<Node>>> {
        let mut branches = Vec::new();
        loop {
            self.skip_x();
            branches.push(self.seq()?);
            self.skip_x();
            if self.peek() == Some('|') {
                self.bump();
                continue;
            }
            break;
        }
        Ok(branches)
    }

    fn seq(&mut self) -> R<Vec<Node>> {
        let mut out: Vec<Node> = Vec::new();
        loop {
            self.skip_x();
            match self.peek() {
                None | Some('|') | Some(')') => break,
                Some('*') | Some('+') | Some('?') | Some('{') => {
                    let p = self.i;
                    return Err(self.e1("repetition operator missing expression", p));
                }
                _ => {}
            }
            let atom = self.atom()?;
            let node = self.quantifiers(atom)?;
            out.push(node);
        }
        Ok(out)
    }

    fn quantifiers(&mut self, atom: Node) -> R<Node> {
        let mut node = atom;
        loop {
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.bump();
                    (0u32, None)
                }
                Some('+') => {
                    self.bump();
                    (1u32, None)
                }
                Some('?') => {
                    self.bump();
                    (0u32, Some(1u32))
                }
                Some('{') => match self.counted()? {
                    Some((a, b)) => (a, b),
                    None => break,
                },
                _ => break,
            };
            let mut greedy = !self.flags.swap;
            if self.peek() == Some('?') {
                self.bump();
                greedy = !greedy;
            }
            node = Node::Rep {
                seq: vec![node],
                min,
                max,
                greedy,
            };
        }
        Ok(node)
    }

    fn counted(&mut self) -> R<Option<(u32, Option<u32>)>> {
        let open = self.i;
        self.bump(); // '{'
        let first: u64 = match self.peek() {
            Some(c) if c.is_ascii_digit() => {
                let ds = self.i;
                let mut n: u64 = 0;
                let mut any = false;
                while let Some(c) = self.peek() {
                    if let Some(d) = c.to_digit(10) {
                        n = match n.checked_mul(10).and_then(|v| v.checked_add(d as u64)) {
                            Some(v) => v,
                            None => {
                                return Err(self.err(
                                    "decimal literal invalid",
                                    vec![(ds, self.i + 1)],
                                ));
                            }
                        };
                        any = true;
                        self.bump();
                    } else {
                        break;
                    }
                }
                if !any {
                    return Err(self.e1(
                        "repetition quantifier expects a valid decimal",
                        self.i,
                    ));
                }
                let _ = ds;
                n
            }
            Some(_) => {
                return Err(self.e1(
                    "repetition quantifier expects a valid decimal",
                    self.i,
                ));
            }
            None => {
                return Err(self.err("unclosed counted repetition", vec![(open, self.i)]));
            }
        };
        let mut second: Option<u64> = None;
        if self.peek() == Some(',') {
            self.bump();
            if self.peek() == Some('}') {
                second = None;
            } else {
                let ds = self.i;
                let mut n: u64 = 0;
                let mut any = false;
                while let Some(c) = self.peek() {
                    if let Some(d) = c.to_digit(10) {
                        n = match n.checked_mul(10).and_then(|v| v.checked_add(d as u64)) {
                            Some(v) => v,
                            None => {
                                return Err(self.err(
                                    "decimal literal invalid",
                                    vec![(ds, self.i + 1)],
                                ));
                            }
                        };
                        any = true;
                        self.bump();
                    } else {
                        break;
                    }
                }
                if !any {
                    return Err(self.e1(
                        "repetition quantifier expects a valid decimal",
                        self.i,
                    ));
                }
                second = Some(n);
            }
        }
        if self.peek() != Some('}') {
            return Err(self.err("unclosed counted repetition", vec![(open, self.i)]));
        }
        self.bump(); // '}'
        if let Some(hi) = second {
            if hi < first {
                let mut end = self.i;
                if self.peek() == Some('?') {
                    end += 1;
                }
                return Err(self.err(
                    "invalid repetition count range, the start must be <= the end",
                    vec![(open, end)],
                ));
            }
        }
        if second.is_none() && first > u32::MAX as u64 {
            let ds = open + 1;
            return Err(self.err("decimal literal invalid", vec![(ds, self.i)]));
        }
        Ok(Some((
            first as u32,
            second.map(|v| v as u32),
        )))
    }

    fn atom(&mut self) -> R<Node> {
        let c = self.peek().unwrap();
        match c {
            '.' => {
                self.bump();
                Ok(Node::Any)
            }
            '^' => {
                self.bump();
                Ok(Node::StartLine)
            }
            '$' => {
                self.bump();
                Ok(Node::EndLine)
            }
            '[' => self.class(),
            '(' => self.group(),
            '\\' => self.escape(),
            _ => {
                self.bump();
                Ok(Node::Lit(c))
            }
        }
    }

    fn group(&mut self) -> R<Node> {
        let open = self.i;
        self.bump(); // '('
        let saved_flags = self.flags;
        let mut scoped = false;
        let mut flags_changed = false;
        if self.peek() == Some('?') {
            self.bump();
            match self.peek() {
                Some(':') => {
                    self.bump();
                }
                Some('P') => {
                    let p = self.i;
                    self.bump();
                    if self.peek() == Some('<') {
                        self.bump();
                        let name_start = self.i;
                        let mut name = String::new();
                        loop {
                            match self.peek() {
                                Some('>') => {
                                    self.bump();
                                    break;
                                }
                                Some(c) if c.is_alphanumeric() || c == '_' => {
                                    name.push(c);
                                    self.bump();
                                }
                                Some(_) => {
                                    return Err(self.e1(
                                        "unrecognized syntax in capture group name",
                                        self.i,
                                    ));
                                }
                                None => {
                                    return Err(self.e1("unclosed capture group name", self.i));
                                }
                            }
                        }
                        if name.is_empty() {
                            return Err(self.e1("empty capture group name", name_start));
                        }
                        if let Some((_, first_pos)) = self.names.iter().find(|(n, _)| *n == name) {
                            let fp = *first_pos;
                            return Err(self.err(
                                "duplicate capture group name",
                                vec![(fp, fp + 1), (p + 2, p + 3)],
                            ));
                        }
                        self.names.push((name, p + 2));
                    } else {
                        return Err(self.e1("unrecognized flag", p));
                    }
                }
                Some(c) if "imsxUu-".contains(c) => {
                    flags_changed = true;
                    let mut neg = false;
                    let mut seen: Vec<(char, usize)> = Vec::new();
                    loop {
                        match self.peek() {
                            None => {
                                return Err(self.e1("expected flag but got end of regex", self.i));
                            }
                            Some('-') => {
                                if neg {
                                    return Err(self.e1("duplicate flag", self.i));
                                }
                                neg = true;
                                self.bump();
                            }
                            Some(f) if "imsxUu".contains(f) => {
                                if let Some((_, fp)) = seen.iter().find(|(x, _)| *x == f) {
                                    let a = *fp;
                                    let b = self.i;
                                    let mut spans = vec![(a, a + 1), (b, b + 1)];
                                    spans.sort();
                                    return Err(self.err("duplicate flag", spans));
                                }
                                seen.push((f, self.i));
                                match f {
                                    'i' => self.flags.ci = !neg,
                                    'U' => self.flags.swap = !neg,
                                    'x' => self.flags.x = !neg,
                                    _ => {}
                                }
                                self.bump();
                            }
                            Some(':') => {
                                self.bump();
                                scoped = true;
                                let branches = self.alt()?;
                                if self.peek() != Some(')') {
                                    return Err(self.e1("unclosed group", open));
                                }
                                self.bump();
                                self.flags = saved_flags;
                                return Ok(Node::Alt(branches));
                            }
                            Some(_) => {
                                return Err(self.e1("unrecognized flag", self.i));
                            }
                        }
                    }
                }
                Some(_) => {
                    let p = self.i;
                    return Err(self.e1("unrecognized flag", p));
                }
                None => {
                    return Err(self.e1("unclosed group", open));
                }
            }
        }
        let branches = self.alt()?;
        if self.peek() != Some(')') {
            return Err(self.e1("unclosed group", open));
        }
        self.bump();
        if flags_changed && !scoped {
            self.flags = saved_flags;
        }
        if branches.len() == 1 {
            Ok(Node::Group(branches.pop().unwrap()))
        } else {
            Ok(Node::Group(vec![Node::Alt(branches)]))
        }
    }

    fn escape(&mut self) -> R<Node> {
        let start = self.i;
        self.bump(); // '\\'
        let c = match self.peek() {
            Some(c) => c,
            None => {
                return Err(self.e1(
                    "incomplete escape sequence, reached end of pattern prematurely",
                    start,
                ));
            }
        };
        self.bump();
        match c {
            'd' => Ok(class_posix(Posix::Digit, false)),
            'D' => Ok(class_posix(Posix::Digit, true)),
            'w' => Ok(class_posix(Posix::Word, false)),
            'W' => Ok(class_posix(Posix::Word, true)),
            's' => Ok(class_posix(Posix::Space, false)),
            'S' => Ok(class_posix(Posix::Space, true)),
            'p' | 'P' => {
                let neg = c == 'P';
                let name: String;
                let mut end = self.i;
                if self.peek() == Some('{') {
                    self.bump();
                    let mut n = String::new();
                    loop {
                        match self.peek() {
                            Some('}') => {
                                self.bump();
                                break;
                            }
                            Some(ch) => {
                                n.push(ch);
                                self.bump();
                            }
                            None => {
                                return Err(self.e1(
                                    "incomplete escape sequence, reached end of pattern prematurely",
                                    start,
                                ));
                            }
                        }
                    }
                    name = n;
                    end = self.i;
                } else {
                    match self.peek() {
                        Some(ch) if ch.is_ascii_alphabetic() => {
                            name = ch.to_string();
                            self.bump();
                            end = self.i;
                        }
                        _ => {
                            return Err(self.e1(
                                "incomplete escape sequence, reached end of pattern prematurely",
                                end,
                            ));
                        }
                    }
                }
                if !known_property(&name) {
                    return Err(self.err("Unicode property not found", vec![(start, end)]));
                }
                Ok(Node::Class(Class {
                    items: vec![Item::Prop(name, neg)],
                    neg: false,
                }))
            }
            'b' => Ok(Node::WordB),
            'B' => Ok(Node::NotWordB),
            'A' => Ok(Node::StartText),
            'z' => Ok(Node::EndText),
            'Z' => Ok(Node::EndText),
            'n' => Ok(Node::Lit('\n')),
            'r' => Ok(Node::Lit('\r')),
            't' => Ok(Node::Lit('\t')),
            'f' => Ok(Node::Lit('\u{c}')),
            'v' => Ok(Node::Lit('\u{b}')),
            'a' => Ok(Node::Lit('\u{7}')),
            '0' => Ok(Node::Lit('\0')),
            'x' | 'u' => {
                let v = self.hex_escape(c, start)?;
                match char::from_u32(v) {
                    Some(ch) => Ok(Node::Lit(ch)),
                    None => Err(self.e1("invalid scalar value", start)),
                }
            }
            '1'..='9' => Err(self.err(
                "backreferences are not supported",
                vec![(start, self.i)],
            )),
            _ => {
                if c.is_ascii_alphanumeric() {
                    return Err(self.err(
                        "unrecognized escape sequence",
                        vec![(start, self.i)],
                    ));
                }
                Ok(Node::Lit(c))
            }
        }
    }

    fn hex_escape(&mut self, which: char, start: usize) -> R<u32> {
        let mut v: u32 = 0;
        if self.peek() == Some('{') {
            self.bump();
            let mut any = false;
            while let Some(ch) = self.peek() {
                if ch == '}' {
                    self.bump();
                    break;
                }
                if let Some(d) = ch.to_digit(16) {
                    v = match v.checked_mul(16).and_then(|x| x.checked_add(d)) {
                        Some(x) => x,
                        None => return Err(self.e1("invalid hexadecimal digit", self.i)),
                    };
                    any = true;
                    self.bump();
                } else {
                    return Err(self.e1("invalid hexadecimal digit", self.i));
                }
            }
            if !any {
                return Err(self.e1("invalid hexadecimal digit", self.i));
            }
        } else {
            let n = if which == 'x' { 2 } else { 4 };
            for _ in 0..n {
                match self.peek() {
                    Some(ch) if ch.is_ascii_hexdigit() => {
                        v = v * 16 + ch.to_digit(16).unwrap();
                        self.bump();
                    }
                    _ => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            start,
                        ));
                    }
                }
            }
        }
        Ok(v)
    }

    fn class(&mut self) -> R<Node> {
        let open = self.i;
        self.bump(); // '['
        let mut neg = false;
        if self.peek() == Some('^') {
            neg = true;
            self.bump();
        }
        let mut items: Vec<Item> = Vec::new();
        let mut first = true;
        let mut consumed_close = false;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => {
                    let mut width = 1;
                    if neg {
                        width += 1;
                    }
                    if consumed_close {
                        width += 1;
                    }
                    return Err(self.err(
                        "unclosed character class",
                        vec![(open, open + width)],
                    ));
                }
            };
            if c == ']' {
                if first {
                    consumed_close = true;
                    self.bump();
                    items.push(Item::Range(']', ']'));
                    first = false;
                    continue;
                }
                self.bump();
                break;
            }
            first = false;
            if c == '[' && self.at(self.i + 1) == Some(':') {
                // POSIX class, or a nested class whose first item starts with ':'
                let save = self.i;
                let mut j = self.i + 2;
                let mut name = String::new();
                let mut found = false;
                while j < self.c.len() {
                    if self.c[j] == ':' && j + 1 < self.c.len() && self.c[j + 1] == ']' {
                        found = true;
                        break;
                    }
                    name.push(self.c[j]);
                    j += 1;
                }
                if found && posix_by_name(&name).is_some() {
                    items.push(Item::Posix(posix_by_name(&name).unwrap()));
                    self.i = j + 2;
                    continue;
                }
                self.i = save;
                let nested = self.class()?;
                if let Node::Class(cl) = nested {
                    items.push(Item::Class(cl));
                }
                continue;
            }
            if c == '[' {
                let nested = self.class()?;
                if let Node::Class(cl) = nested {
                    items.push(Item::Class(cl));
                }
                continue;
            }
            if c == '\\' {
                let es = self.i;
                self.bump();
                let e = match self.peek() {
                    Some(e) => e,
                    None => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            es,
                        ));
                    }
                };
                self.bump();
                match e {
                    'd' => items.push(Item::Class(class_posix_cls(Posix::Digit, false))),
                    'D' => items.push(Item::Class(class_posix_cls(Posix::Digit, true))),
                    'w' => items.push(Item::Class(class_posix_cls(Posix::Word, false))),
                    'W' => items.push(Item::Class(class_posix_cls(Posix::Word, true))),
                    's' => items.push(Item::Class(class_posix_cls(Posix::Space, false))),
                    'S' => items.push(Item::Class(class_posix_cls(Posix::Space, true))),
                    'p' | 'P' => {
                        let mut name = String::new();
                        let mut end = self.i;
                        if self.peek() == Some('{') {
                            self.bump();
                            while let Some(ch) = self.peek() {
                                if ch == '}' {
                                    self.bump();
                                    break;
                                }
                                name.push(ch);
                                self.bump();
                            }
                            end = self.i;
                        } else if let Some(ch) = self.peek() {
                            name = ch.to_string();
                            self.bump();
                            end = self.i;
                        } else {
                            return Err(self.e1(
                                "incomplete escape sequence, reached end of pattern prematurely",
                                es,
                            ));
                        }
                        if !known_property(&name) {
                            return Err(self.err("Unicode property not found", vec![(es, end)]));
                        }
                        items.push(Item::Prop(name, e == 'P'));
                    }
                    'n' => items.push(Item::Range('\n', '\n')),
                    'r' => items.push(Item::Range('\r', '\r')),
                    't' => items.push(Item::Range('\t', '\t')),
                    'f' => items.push(Item::Range('\u{c}', '\u{c}')),
                    'v' => items.push(Item::Range('\u{b}', '\u{b}')),
                    'a' => items.push(Item::Range('\u{7}', '\u{7}')),
                    'b' => items.push(Item::Range('\u{8}', '\u{8}')),
                    '0' => items.push(Item::Range('\0', '\0')),
                    'x' | 'u' => {
                        let v = self.hex_escape(e, es)?;
                        match char::from_u32(v) {
                            Some(ch) => items.push(Item::Range(ch, ch)),
                            None => return Err(self.e1("invalid scalar value", es)),
                        }
                    }
                    other => items.push(Item::Range(other, other)),
                }
                continue;
            }
            self.bump();
            if self.peek() == Some('-')
                && self.at(self.i + 1).is_some()
                && self.at(self.i + 1) != Some(']')
            {
                self.bump(); // '-'
                let hi = match self.peek() {
                    Some('\\') => {
                        let es = self.i;
                        self.bump();
                        let e = match self.peek() {
                            Some(e) => e,
                            None => {
                                return Err(self.e1(
                                    "incomplete escape sequence, reached end of pattern prematurely",
                                    es,
                                ));
                            }
                        };
                        self.bump();
                        match e {
                            'n' => '\n',
                            'r' => '\r',
                            't' => '\t',
                            'f' => '\u{c}',
                            'v' => '\u{b}',
                            'a' => '\u{7}',
                            'x' | 'u' => {
                                let v = self.hex_escape(e, es)?;
                                match char::from_u32(v) {
                                    Some(ch) => ch,
                                    None => return Err(self.e1("invalid scalar value", es)),
                                }
                            }
                            other => other,
                        }
                    }
                    Some(ch) => {
                        self.bump();
                        ch
                    }
                    None => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            self.i,
                        ));
                    }
                };
                if hi < c {
                    let lo = self.i - (2 + hi.len_utf8().max(1) - hi.len_utf8());
                    let _ = lo;
                    // span covers "start-end"
                    let end_pos = self.i;
                    let start_pos = end_pos - 2 - char_len(&self.pat, c) + 1;
                    return Err(self.err(
                        "invalid character class range, the start must be <= the end",
                        vec![(start_pos - 1, end_pos)],
                    ));
                }
                items.push(Item::Range(c, hi));
            } else {
                items.push(Item::Range(c, c));
            }
        }
        Ok(Node::Class(Class { items, neg }))
    }
}

fn char_len(pat: &str, c: char) -> usize {
    let _ = pat;
    c.len_utf8()
}

fn class_posix(p: Posix, neg: bool) -> Node {
    Node::Class(class_posix_cls(p, neg))
}

fn class_posix_cls(p: Posix, neg: bool) -> Class {
    Class {
        items: vec![Item::Posix(p)],
        neg,
    }
}

fn posix_by_name(n: &str) -> Option<Posix> {
    match n {
        "alnum" => Some(Posix::Alnum),
        "alpha" => Some(Posix::Alpha),
        "ascii" => Some(Posix::Ascii),
        "blank" => Some(Posix::Blank),
        "cntrl" => Some(Posix::Cntrl),
        "digit" => Some(Posix::Digit),
        "graph" => Some(Posix::Graph),
        "lower" => Some(Posix::Lower),
        "print" => Some(Posix::Print),
        "punct" => Some(Posix::Punct),
        "space" => Some(Posix::Space),
        "upper" => Some(Posix::Upper),
        "word" => Some(Posix::Word),
        "xdigit" => Some(Posix::Xdigit),
        _ => None,
    }
}

// ---------------------------------------------------------------- matcher

struct Ctx {
    ci: bool,
}

enum Cont<'a> {
    Nil,
    Seq(&'a [Node], &'a Cont<'a>),
    Rep(&'a RepFrame<'a>),
}

struct RepFrame<'a> {
    seq: &'a [Node],
    rest: &'a [Node],
    cont: &'a Cont<'a>,
    min: u32,
    max: Option<u32>,
    greedy: bool,
    count: u32,
    start: usize,
}

struct Steps(u64);

const STEP_LIMIT: u64 = 8_000_000;

fn top_branches(root: &Node) -> Vec<Vec<Node>> {
    match root {
        Node::Alt(b) => b.clone(),
        other => vec![vec![other.clone()]],
    }
}

impl Regex {
    pub fn is_match(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        let ctx = Ctx { ci: self.ci };
        let branches = top_branches(&self.root);
        for start in 0..=chars.len() {
            let mut steps = Steps(0);
            for b in branches.iter() {
                if m_seq(b, &chars[..], start, &Cont::Nil, &ctx, &mut steps) {
                    return true;
                }
            }
        }
        false
    }
}

fn m_seq(
    nodes: &[Node],
    text: &[char],
    pos: usize,
    cont: &Cont,
    ctx: &Ctx,
    steps: &mut Steps,
) -> bool {
    if steps.0 > STEP_LIMIT {
        return false;
    }
    steps.0 += 1;
    if nodes.is_empty() {
        match cont {
            Cont::Nil => true,
            Cont::Seq(rest, tail) => m_seq(rest, text, pos, tail, ctx, steps),
            Cont::Rep(frame) => {
                if pos == frame.start && frame.count >= frame.min {
                    return m_seq(frame.rest, text, pos, frame.cont, ctx, steps);
                }
                let f2 = RepFrame {
                    seq: frame.seq,
                    rest: frame.rest,
                    cont: frame.cont,
                    min: frame.min,
                    max: frame.max,
                    greedy: frame.greedy,
                    count: frame.count + 1,
                    start: pos,
                };
                rep_match(&f2, text, pos, ctx, steps)
            }
        }
    } else {
        let (first, rest) = nodes.split_first().unwrap();
        m_node(first, rest, text, pos, cont, ctx, steps)
    }
}

fn rep_match(frame: &RepFrame, text: &[char], pos: usize, ctx: &Ctx, steps: &mut Steps) -> bool {
    let can_more = frame.max.map_or(true, |m| frame.count < m);
    if frame.greedy {
        if can_more {
            let c = Cont::Rep(frame);
            if m_seq(frame.seq, text, pos, &c, ctx, steps) {
                return true;
            }
        }
        if frame.count >= frame.min {
            return m_seq(frame.rest, text, pos, frame.cont, ctx, steps);
        }
        false
    } else {
        if frame.count >= frame.min && m_seq(frame.rest, text, pos, frame.cont, ctx, steps) {
            return true;
        }
        if can_more {
            let c = Cont::Rep(frame);
            if m_seq(frame.seq, text, pos, &c, ctx, steps) {
                return true;
            }
        }
        false
    }
}

fn m_node(
    node: &Node,
    rest: &[Node],
    text: &[char],
    pos: usize,
    cont: &Cont,
    ctx: &Ctx,
    steps: &mut Steps,
) -> bool {
    if steps.0 > STEP_LIMIT {
        return false;
    }
    steps.0 += 1;
    match node {
        Node::Lit(c) => {
            if pos < text.len() && (text[pos] == *c || (ctx.ci && ci_eq(text[pos], *c))) {
                m_seq(rest, text, pos + 1, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::Any => {
            if pos < text.len() && text[pos] != '\n' {
                m_seq(rest, text, pos + 1, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::Class(cl) => {
            if pos < text.len() && cl.matches(text[pos], ctx.ci) {
                m_seq(rest, text, pos + 1, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::StartLine => {
            if pos == 0 {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::EndLine => {
            if pos == text.len() {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::StartText => {
            if pos == 0 {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::EndText => {
            if pos == text.len() {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::WordB => {
            if at_word_boundary(text, pos) {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::NotWordB => {
            if !at_word_boundary(text, pos) {
                m_seq(rest, text, pos, cont, ctx, steps)
            } else {
                false
            }
        }
        Node::Group(seq) => {
            let c = Cont::Seq(rest, cont);
            m_seq(seq, text, pos, &c, ctx, steps)
        }
        Node::Alt(branches) => {
            let c = Cont::Seq(rest, cont);
            for b in branches.iter() {
                if m_seq(b, text, pos, &c, ctx, steps) {
                    return true;
                }
            }
            false
        }
        Node::Rep {
            seq,
            min,
            max,
            greedy,
        } => {
            let frame = RepFrame {
                seq,
                rest,
                cont,
                min: *min,
                max: *max,
                greedy: *greedy,
                count: 0,
                start: pos,
            };
            rep_match(&frame, text, pos, ctx, steps)
        }
    }
}

fn at_word_boundary(text: &[char], pos: usize) -> bool {
    let before = if pos == 0 { None } else { Some(text[pos - 1]) };
    let after = text.get(pos).copied();
    let b = before.map_or(false, is_word);
    let a = after.map_or(false, is_word);
    b != a
}

// approximate compiled size, used to reproduce the regex crate's
// "Compiled regex exceeds size limit" error
fn size_of(nodes: &[Node]) -> u64 {
    let mut total = 0u64;
    for n in nodes {
        total += size_node(n);
    }
    total
}

fn size_node(n: &Node) -> u64 {
    match n {
        Node::Lit(_) | Node::Any | Node::Class(_) | Node::StartLine | Node::EndLine
        | Node::StartText | Node::EndText | Node::WordB | Node::NotWordB => 1,
        Node::Group(seq) => 2 + size_of(seq),
        Node::Alt(branches) => {
            let mut t = 1;
            for b in branches {
                t += size_of(b);
            }
            t
        }
        Node::Rep { seq, min, max, .. } => {
            let inner = size_of(seq).max(1);
            match max {
                Some(m) => {
                    let m = *m as u64;
                    m.saturating_mul(inner).saturating_add(1)
                }
                None => {
                    let m = *min as u64;
                    m.saturating_add(1).saturating_mul(inner).saturating_add(2)
                }
            }
        }
    }
}

pub fn compile(pat: &str) -> Result<Regex, RegexError> {
    let chars: Vec<char> = pat.chars().collect();
    let mut p = Parser {
        pat: pat.to_string(),
        c: chars,
        i: 0,
        flags: Flags::new(),
        names: Vec::new(),
    };
    let root = p.parse()?;
    let size = top_branches(&root).iter().map(|b| size_of(b)).sum::<u64>();
    if size * 16 > 1048576 * 5 {
        return Err(RegexError {
            pattern: pat.to_string(),
            spans: Vec::new(),
            msg: "Compiled regex exceeds size limit of 1048576".to_string(),
        });
    }
    let ci = p.flags.ci;
    Ok(Regex { root, ci })
}
