    NumberExpected(usize),
    UnknownUnit { start: usize, unit: String },
    NumberOverflow,
    Empty,
}

impl std::fmt::Display for DurError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            DurError::InvalidCharacter(o) => write!(f, "invalid character at {}", o),
            DurError::NumberExpected(o) => write!(f, "expected number at {}", o),
            DurError::UnknownUnit { start, unit } => {
                write!(f, "unknown unit at {}-{}", start, start + unit.chars().count())
            }
            DurError::NumberOverflow => write!(f, "number is too large"),
            DurError::Empty => write!(f, "value was empty"),
        }
    }
}

const SECOND: u64 = 1_000_000_000;

fn unit_ns(u: &str) -> Option<u64> {
    match u {
        "ns" | "nsec" => Some(1),
        "us" | "usec" => Some(1_000),
        "ms" | "msec" => Some(1_000_000),
        "s" | "sec" | "secs" | "second" | "seconds" => Some(SECOND),
        "m" | "min" | "mins" | "minute" | "minutes" => Some(60 * SECOND),
        "h" | "hr" | "hrs" | "hour" | "hours" => Some(3600 * SECOND),
        "d" | "day" | "days" => Some(86400 * SECOND),
        "w" | "week" | "weeks" => Some(86400 * 7 * SECOND),
        "M" | "month" | "months" => Some(86400 * 30 * SECOND),
        "y" | "year" | "years" => Some(86400 * 365 * SECOND),
        _ => None,
    }
}

/// Parses strings like "1h30m", "5s", "100ms" (whitespace is insignificant).
pub fn parse_duration(s: &str) -> Result<Duration, DurError> {
    let b = s.as_bytes();
    let len = b.len();
    let mut pos = 0usize; // byte index of the next char to examine
    let mut secs: u64 = 0;
    let mut nanos: u64 = 0;
    let mut started = false;

    // state: expecting a number
    loop {
        // skip whitespace
        let mut skipped_ws = false;
        while pos < len {
            let c = b[pos] as char;
            if c.is_ascii() && c.is_whitespace() {
                pos += 1;
                skipped_ws = true;
            } else if !c.is_ascii() {
                // unicode whitespace
                let rest = &s[pos..];
                let ch = rest.chars().next().unwrap();
                if ch.is_whitespace() {
                    pos += ch.len_utf8();
                    skipped_ws = true;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        let _ = skipped_ws;
        if !started && pos >= len {
            return Err(DurError::Empty);
        }
        if pos >= len {
            break;
        }
        // read digits (whitespace insignificant inside the number)
        let num_start = pos;
        let mut n: u64 = 0;
        let mut any = false;
        while pos < len {
            let c = b[pos] as char;
            if c.is_ascii_digit() {
                n = match n.checked_mul(10).and_then(|v| v.checked_add(c as u64 - '0' as u64)) {
                    Some(v) => v,
                    None => return Err(DurError::NumberOverflow),
                };
                any = true;
                pos += 1;
            } else if c.is_ascii_whitespace() {
                pos += 1;
            } else if !c.is_ascii() {
                let ch = s[pos..].chars().next().unwrap();
                if ch.is_whitespace() {
                    pos += ch.len_utf8();
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        if !any {
            if !started {
                return Err(DurError::NumberExpected(0));
            }
            // after a unit: expected a number
            return Err(DurError::NumberExpected(num_start));
        }
        started = true;
        // now expect a unit
        while pos < len {
            let c = b[pos] as char;
            if c.is_ascii_whitespace() {
                pos += 1;
            } else if !c.is_ascii() {
                let ch = s[pos..].chars().next().unwrap();
                if ch.is_whitespace() {
                    pos += ch.len_utf8();
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        if pos >= len {
            return Err(DurError::UnknownUnit {
                start: len,
                unit: String::new(),
            });
        }
        let c = b[pos] as char;
        if !c.is_ascii_alphabetic() {
            return Err(DurError::InvalidCharacter(pos));
        }
        let unit_start = pos;
        let mut unit = String::new();
        while pos < len {
            let ch = s[pos..].chars().next().unwrap();
            if ch.is_ascii_alphabetic() {
                unit.push(ch);
                pos += ch.len_utf8();
            } else {
                break;
            }
        }
        let mult = match unit_ns(&unit) {
            Some(m) => m,
            None => {
                return Err(DurError::UnknownUnit {
                    start: unit_start,
                    unit: unit.clone(),
                });
            }
        };
        let sp = mult / SECOND;
        let np = mult % SECOND;
        secs = match secs.checked_add(n.checked_mul(sp).ok_or(DurError::NumberOverflow)?) {
            Some(v) => v,
            None => return Err(DurError::NumberOverflow),
        };
        nanos = match nanos.checked_add(n.checked_mul(np).ok_or(DurError::NumberOverflow)?) {
            Some(v) => v,
            None => return Err(DurError::NumberOverflow),
        };
        secs = secs.saturating_add(nanos / SECOND);
        nanos %= SECOND;
        // loop again: expect another number
    }
    Ok(Duration::new(secs, nanos as u32))
}
