// Duration parsing compatible with the error messages produced by
// `humantime::parse_duration`.
use std::time::Duration;

#[derive(Debug)]
pub enum DurError {
    InvalidCharacter(usize),
    NumberExpected(usize),
    UnknownUnit { start: usize, unit: String },
    NumberOverflow,
    Empty,
}

impl std::fmt::Display for DurError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            DurError::InvalidCharacter(o) => write!(f, "invalid character at {}", o),
            DurError::NumberExpected(o) => write!(f, "expected number at {}", o),
            DurError::UnknownUnit { start, unit } => {
                write!(f, "unknown unit at {}-{}", start, start + unit.chars().count())
            }
            DurError::NumberOverflow => write!(f, "number is too large"),
            DurError::Empty => write!(f, "value was empty"),
        }
    }
}

const SECOND: u64 = 1_000_000_000;

fn unit_ns(u: &str) -> Option<u64> {
    match u {
        "ns" | "nsec" => Some(1),
        "us" | "usec" => Some(1_000),
        "ms" | "msec" => Some(1_000_000),
        "s" | "sec" | "secs" | "second" | "seconds" => Some(SECOND),
        "m" | "min" | "mins" | "minute" | "minutes" => Some(60 * SECOND),
        "h" | "hr" | "hrs" | "hour" | "hours" => Some(3600 * SECOND),
        "d" | "day" | "days" => Some(86400 * SECOND),
        "w" | "week" | "weeks" => Some(86400 * 7 * SECOND),
        "M" | "month" | "months" => Some(86400 * 30 * SECOND),
        "y" | "year" | "years" => Some(86400 * 365 * SECOND),
        _ => None,
    }
}

fn is_ws(s: &str, pos: usize) -> (bool, usize) {
    if pos >= s.len() {
        return (false, 0);
    }
    let b = s.as_bytes()[pos];
    if b < 128 {
        ((b as char).is_whitespace(), 1)
    } else {
        let ch = s[pos..].chars().next().unwrap();
        (ch.is_whitespace(), ch.len_utf8())
    }
}

fn skip_ws(s: &str, mut pos: usize) -> usize {
    loop {
        let (w, n) = is_ws(s, pos);
        if w {
            pos += n;
        } else {
            break;
        }
    }
    pos
}

/// Parses strings such as "1h30m", "5s", "100ms" (whitespace insignificant).
pub fn parse_duration(s: &str) -> Result<Duration, DurError> {
    let len = s.len();
    let mut pos = 0usize;
    let mut secs: u64 = 0;
    let mut nanos: u64 = 0;
    let mut err_start: usize = 0;
    let mut first = true;

    loop {
        // --- number -------------------------------------------------------
        let mut n: u64 = 0;
        let mut any = false;
        loop {
            if pos >= len {
                break;
            }
            let c = s.as_bytes()[pos] as char;
            if c.is_ascii_digit() {
                n = match n.checked_mul(10).and_then(|v| v.checked_add(c as u64 - '0' as u64)) {
                    Some(v) => v,
                    None => return Err(DurError::NumberOverflow),
                };
                any = true;
                pos += 1;
            } else {
                let (w, k) = is_ws(s, pos);
                if w {
                    pos += k;
                } else {
                    break;
                }
            }
        }
        if !any {
            if first && skip_ws(s, 0) >= len {
                return Err(DurError::Empty);
            }
            return Err(DurError::NumberExpected(err_start));
        }
        first = false;

        // --- unit ---------------------------------------------------------
        pos = skip_ws(s, pos);
        if pos >= len {
            return Err(DurError::UnknownUnit {
                start: len,
                unit: String::new(),
            });
        }
        let c = s.as_bytes()[pos] as char;
        if !c.is_ascii_alphabetic() {
            return Err(DurError::InvalidCharacter(pos));
        }
        let unit_start = pos;
        let mut unit = String::new();
        while pos < len {
            let ch = s[pos..].chars().next().unwrap();
            if ch.is_ascii_alphabetic() {
                unit.push(ch);
                pos += ch.len_utf8();
            } else {
                break;
            }
        }
        let mult = match unit_ns(&unit) {
            Some(m) => m,
            None => {
                return Err(DurError::UnknownUnit {
                    start: unit_start,
                    unit: unit.clone(),
                });
            }
        };
        let sp = mult / SECOND;
        let np = mult % SECOND;
        secs = match secs.checked_add(n.checked_mul(sp).ok_or(DurError::NumberOverflow)?) {
            Some(v) => v,
            None => return Err(DurError::NumberOverflow),
        };
        nanos = match nanos.checked_add(n.checked_mul(np).ok_or(DurError::NumberOverflow)?) {
            Some(v) => v,
            None => return Err(DurError::NumberOverflow),
        };
        secs = secs.saturating_add(nanos / SECOND);
        nanos %= SECOND;

        // --- maybe another number follows ---------------------------------
        if pos >= len {
            break;
        }
        let (w, k) = is_ws(s, pos);
        if w {
            pos += k;
            err_start = pos;
            pos = skip_ws(s, pos);
            if pos >= len {
                break;
            }
            if !s.as_bytes()[pos].is_ascii_digit() {
                return Err(DurError::NumberExpected(err_start));
            }
        } else {
            let c2 = s.as_bytes()[pos] as char;
            if !c2.is_ascii_digit() {
                return Err(DurError::InvalidCharacter(pos));
            }
            err_start = pos;
        }
    }
    Ok(Duration::new(secs, nanos as u32))
}
