    let mut v: u64 = 0;
    for k in 0..n {
        let c = b[i + k] as char;
        if !c.is_ascii_digit() {
            return None;
        }
        v = v * 10 + (c as u64 - '0' as u64);
    }
    Some(v)
}

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: i64, m: u64) -> u64 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => 0,
    }
}

/// days since 1970-01-01 for the given civil date
fn days_from_civil(y: i64, m: u64, d: u64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (m as i64 + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub struct Moment {
    pub secs: u64,
    pub nanos: u32,
}

pub fn parse_time(s: &str) -> Result<Moment, TimeError> {
    let b = s.as_bytes();
    let mut t = s;
    // optional trailing 'Z'
    if t.ends_with('Z') {
        t = &t[..t.len() - 1];
    }
    if t.len() < 19 {
        return Err(TimeError::Invalid);
    }
    let tb = t.as_bytes();
    let sep = tb[10];
    if sep != b' ' && sep != b'T' {
        return Err(TimeError::Invalid);
    }
    let year = match digits(t, 0, 4) {
        Some(v) => v,
        None => return Err(TimeError::Invalid),
    };
    if tb[4] != b'-' {
        return Err(TimeError::Invalid);
    }
    let month = match digits(t, 5, 2) {
        Some(v) => v,
        None => return Err(TimeError::Invalid),
    };
    if tb[7] != b'-' {
        return Err(TimeError::Invalid);
    }
    let day = match digits(t, 8, 2) {
        Some(v) => v,
        None => return Err(TimeError::Invalid),
    };
    let hour = match digits(t, 11, 2) {
        Some(v) => v,
        None => return Err(TimeError::Invalid),
    };
    if tb[13] != b':' {
        return Err(TimeError::Invalid);
    }
    let min = match digits(t, 14, 2) {
        Some(v) => v,
        None => return Err(TimeError::Invalid),
    };
    if tb[16] != b':' {
        return Err(TimeError::Invalid);
    }
    let sec = match digits(t, 17, 2) {
        Some(v) => v,
        None => return Err(TimeError::Invalid),
    };
    let mut rest = 19;
    // fractional seconds
    let mut nanos: u32 = 0;
    if rest < t.len() && tb[rest] == b'.' {
        rest += 1;
        let start = rest;
        let mut scale = 100_000_000u64;
        while rest < t.len() && tb[rest].is_ascii_digit() {
            let d = (tb[rest] - b'0') as u64;
            nanos = (nanos as u64 + d * scale) as u32;
            if scale > 1 {
                scale /= 10;
            }
            rest += 1;
        }
        let _ = start;
    }
    if rest != t.len() {
        return Err(TimeError::Invalid);
    }
    if !(1..=12).contains(&month) {
        return Err(TimeError::OutOfRange);
    }
    if !(1..=days_in_month(year as i64, month)).contains(&day) {
        return Err(TimeError::OutOfRange);
    }
    if hour > 23 {
        return Err(TimeError::OutOfRange);
    }
    if min > 59 {
        return Err(TimeError::OutOfRange);
    }
    if sec > 60 {
        return Err(TimeError::OutOfRange);
    }
    let days = days_from_civil(year as i64, month, day);
    let total = days * 86400 + (hour * 3600 + min * 60 + sec) as i64;
    if total < 0 {
        return Err(TimeError::OutOfRange);
    }
    Ok(Moment {
        secs: total as u64,
        nanos,
    })
}
