        Ok(cfg) => {
            let code = run(&cfg);
            std::process::exit(code);
        }
        Err(e) => {
            match e.kind {
                ErrKind::Help => {
                    print!("{}", help_text(&bin));
                    std::process::exit(0);
                }
                ErrKind::Version => {
                    println!("{} {}", APP, VER);
                    std::process::exit(0);
                }
                ErrKind::NoCommand => {
                    println!("No command supplied, exiting.");
                    std::process::exit(0);
                }
                _ => {
                    eprint!("{}", e.render());
                    std::process::exit(1);
                }
            }
        }
    }
}
