mod duration;
mod re;
mod timestamp;

use std::env;
use std::fs::{self, File, OpenOptions};
use std::io::{Read, Seek, SeekFrom};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

const APP: &str = "loop";
const VER: &str = "0.6.1";
const AUTHOR: &str = "Rich Jones <miserlou@gmail.com>";
const ABOUT: &str = "UNIX's missing `loop` command";

struct OptDef {
    name: &'static str,
    long: &'static str,
    short: Option<char>,
    val: &'static str,
    default: Option<&'static str>,
}

struct FlagDef {
    name: &'static str,
    long: &'static str,
    short: Option<char>,
}

const OPTS: [OptDef; 10] = [
    OptDef { name: "count_by", long: "count-by", short: Some('b'), val: "count_by", default: Some("1") },
    OptDef { name: "every", long: "every", short: Some('e'), val: "every", default: Some("1us") },
    OptDef { name: "ffor", long: "for", short: None, val: "ffor", default: None },
    OptDef { name: "for_duration", long: "for-duration", short: Some('d'), val: "for_duration", default: None },
    OptDef { name: "num", long: "num", short: Some('n'), val: "num", default: None },
    OptDef { name: "offset", long: "offset", short: Some('o'), val: "offset", default: Some("0") },
    OptDef { name: "until_contains", long: "until-contains", short: Some('c'), val: "until_contains", default: None },
    OptDef { name: "until_error", long: "until-error", short: Some('r'), val: "until_error", default: None },
    OptDef { name: "until_match", long: "until-match", short: Some('m'), val: "until_match", default: None },
    OptDef { name: "until_time", long: "until-time", short: Some('t'), val: "until_time", default: None },
];

const FLAGS: [FlagDef; 10] = [
    FlagDef { name: "error_duration", long: "error-duration", short: Some('D') },
    FlagDef { name: "help", long: "help", short: Some('h') },
    FlagDef { name: "only_last", long: "only-last", short: Some('l') },
    FlagDef { name: "stdin", long: "stdin", short: Some('i') },
    FlagDef { name: "summary", long: "summary", short: None },
    FlagDef { name: "until_changes", long: "until-changes", short: Some('C') },
    FlagDef { name: "until_fail", long: "until-fail", short: Some('f') },
    FlagDef { name: "until_same", long: "until-same", short: Some('S') },
    FlagDef { name: "until_success", long: "until-success", short: Some('s') },
    FlagDef { name: "version", long: "version", short: Some('V') },
];

// ---- capture of child output -------------------------------------------------

fn rand_name(seed: &mut u64) -> String {
    const ALPHA: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    let mut name = String::from(".tmp");
    for _ in 0..6 {
        *seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let k = (((*seed) >> 33) as usize) % ALPHA.len();
        name.push(ALPHA[k] as char);
    }
    name
}

// The capture file is created, immediately unlinked and then handed to the
// child as both stdout and stderr.
fn capture_file() -> (File, std::path::PathBuf) {
    let dir = env::temp_dir();
    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(12345);
    seed ^= (std::process::id() as u64).wrapping_mul(0x9e3779b97f4a7c15);
    let name = rand_name(&mut seed);
    let path = dir.join(name);
    let file = OpenOptions::new().read(true).write(true).create_new(true).open(&path).unwrap();
    (file, path)
}

// Read back what the child wrote and turn it into text.
fn read_capture(file: &mut File) -> String {
    let _ = file.seek(SeekFrom::Start(0));
    let mut s = String::new();
    file.read_to_string(&mut s).expect("read failed");
    s
}

// ---- clap-like command line parsing -----------------------------------------

#[derive(PartialEq)]
enum ErrKind {
    Help,
    Version,
    NoCommand,
    Error,
}

struct ClapError {
    kind: ErrKind,
    text: String,
}

impl ClapError {
    fn render(&self) -> &str {
        &self.text
    }
}

struct Colorizer {
    on: bool,
}

impl Colorizer {
    fn error(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good_always(&self, s: &str) -> String {
        format!("\x1b[32m{}\x1b[0m", s)
    }
}

fn usage_line(bin: &str, used: &[String]) -> String {
    if used.is_empty() {
        format!("{} [FLAGS] [OPTIONS] [input]...", bin)
    } else {
        let mut u = bin.to_string();
        for a in used {
            u.push(' ');
            u.push_str(a);
        }
        u
    }
}

fn usage_block(bin: &str, used: &[String]) -> String {
    format!("USAGE:\n    {}", usage_line(bin, used))
}

fn arg_display(name: &str) -> String {
    if let Some(o) = OPTS.iter().find(|o| o.name == name) {
        format!("--{} <{}>", o.long, o.val)
    } else if let Some(f) = FLAGS.iter().find(|f| f.name == name) {
        format!("--{}", f.long)
    } else {
        name.to_string()
    }
}

struct Matched {
    occurs: usize,
    vals: Vec<String>,
}

struct Matcher {
    args: Vec<(&'static str, Matched)>,
}

impl Matcher {
    fn new() -> Matcher {
        Matcher { args: Vec::new() }
    }
    fn touch(&mut self, name: &'static str) {
        match self.args.iter_mut().find(|(n, _)| *n == name) {
            Some((_, m)) => m.occurs += 1,
            None => {
                self.args.push((name, Matched { occurs: 1, vals: Vec::new() }));
            }
        }
    }
    fn add_val(&mut self, name: &'static str, v: String) {
        match self.args.iter_mut().find(|(n, _)| *n == name) {
            Some((_, m)) => m.vals.push(v),
            None => {
                self.args.push((name, Matched { occurs: 1, vals: vec![v] }));
            }
        }
    }
    fn get(&self, name: &str) -> Option<&Matched> {
        self.args.iter().find(|(n, _)| *n == name).map(|(_, m)| m)
    }
    fn value(&self, name: &str) -> Option<&String> {
        self.get(name).and_then(|m| m.vals.first())
    }
    fn has(&self, name: &str) -> bool {
        self.args.iter().any(|(n, _)| *n == name)
    }
    fn names(&self) -> Vec<&'static str> {
        self.args.iter().map(|(n, _)| *n).collect()
    }
}

struct Config {
    cmd: String,
    every: Duration,
    num: i64,
    offset: f64,
    count_by: f64,
    decimals: usize,
    for_list: Option<Vec<String>>,
    read_stdin: bool,
    only_last: bool,
    summary: bool,
    error_duration: bool,
    until_changes: bool,
    until_fail: bool,
    until_same: bool,
    until_success: bool,
    until_contains: Option<String>,
    until_error: Option<i32>,
    until_match: Option<re::Regex>,
    until_time: Option<timestamp::Moment>,
    for_duration: Option<Duration>,
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    let (al, bl) = (ac.len(), bc.len());
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    if al == 1 && bl == 1 {
        return if ac[0] == bc[0] { 1.0 } else { 0.0 };
    }
    let sr = (std::cmp::max(al, bl) / 2) - 1;
    let mut bconsumed = vec![false; bl];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut bmi = 0usize;
    for i in 0..al {
        let minb = if i > sr { std::cmp::max(0, i - sr) } else { 0 };
        let maxb = std::cmp::min(bl - 1, i + sr);
        if minb > maxb {
            continue;
        }
        for j in 0..bl {
            if minb <= j && j <= maxb && ac[i] == bc[j] && !bconsumed[j] {
                bconsumed[j] = true;
                matches += 1.0;
                if j < bmi {
                    transpositions += 1.0;
                }
                bmi = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        return 0.0;
    }
    let jaro = (1.0 / 3.0)
        * ((matches / al as f64) + (matches / bl as f64) + ((matches - transpositions) / matches));
    let mut prefix = 0usize;
    for k in 0..std::cmp::min(al, bl) {
        if ac[k] == bc[k] {
            prefix += 1;
        } else {
            break;
        }
    }
    let jw = jaro + (0.1 * prefix as f64 * (1.0 - jaro));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean(arg: &str) -> Option<&'static str> {
    let mut cands: Vec<&'static str> = Vec::new();
    for o in OPTS.iter() {
        cands.push(o.long);
    }
    for f in FLAGS.iter() {
        cands.push(f.long);
    }
    let mut best: Option<(f64, &'static str)> = None;
    for c in cands {
        let conf = jaro_winkler(arg, c);
        if conf > 0.8 && (best.is_none() || best.unwrap().0 <= conf) {
            best = Some((conf, c));
        }
    }
    best.map(|(_, c)| c)
}

fn help_text(bin: &str) -> String {
    let mut s = String::new();
    s.push_str(&format!("{} {}\n", APP, VER));
    s.push_str(&format!("{}\n", AUTHOR));
    s.push_str(&format!("{}\n", ABOUT));
    s.push_str("\nUSAGE:\n");
    s.push_str(&format!("    {} [FLAGS] [OPTIONS] [input]...\n", bin));
    s.push_str("\nFLAGS:\n");
    s.push_str("    -D, --error-duration    Exit with timeout error code on duration\n");
    s.push_str("    -h, --help              Prints help information\n");
    s.push_str("    -l, --only-last         Only print the output of the last execution of the command\n");
    s.push_str("    -i, --stdin             Read from standard input\n");
    s.push_str("        --summary           Provide a summary\n");
    s.push_str("    -C, --until-changes     Keep going until the output changes\n");
    s.push_str("    -f, --until-fail        Keep going until the command exit status is non-zero\n");
    s.push_str("    -S, --until-same        Keep going until the output changes\n");
    s.push_str("    -s, --until-success     Keep going until the command exit status is zero\n");
    s.push_str("    -V, --version           Prints version information\n");
    s.push_str("\nOPTIONS:\n");
    s.push_str("    -b, --count-by <count_by>                Amount to increment the counter by [default: 1]\n");
    s.push_str("    -e, --every <every>                      How often to iterate. ex., 5s, 1h1m1s1ms1us [default: 1us]\n");
    s.push_str("        --for <ffor>                         A comma-separated list of values, placed into 4ITEM. ex., red,green,blue\n");
    s.push_str("    -d, --for-duration <for_duration>        Keep going until the duration has elapsed (example 1m30s)\n");
    s.push_str("    -n, --num <num>                          Number of iterations to execute\n");
    s.push_str("    -o, --offset <offset>                    Amount to offset the initial counter by [default: 0]\n");
    s.push_str("    -c, --until-contains <until_contains>    Keep going until the output contains this string\n");
    s.push_str("    -r, --until-error <until_error>          Keep going until the command exit status is the value given\n");
    s.push_str("    -m, --until-match <until_match>          Keep going until the output matches this regular expression\n");
    s.push_str("    -t, --until-time <until_time>            Keep going until a future time, ex. \"2018-04-20 04:20:00\" (Times in UTC.)\n");
    s.push_str("\nARGS:\n");
    s.push_str("    <input>...    The command to be looped\n");
    s
}

fn bin_name(a: &std::ffi::OsString) -> String {
    let s = a.to_string_lossy().to_string();
    let mut last = 0usize;
    for (i, c) in s.char_indices() {
        if c == '/' {
            last = i + 1;
        }
    }
    s[last..].to_string()
}

fn add_defaults(m: &mut Matcher) {
    for o in OPTS.iter() {
        if let Some(d) = o.default {
            if m.get(o.name).is_none() {
                m.add_val(o.name, d.to_string());
            }
        }
    }
}

fn used_args(m: &Matcher) -> Vec<String> {
    let mut names: Vec<&'static str> = m.names();
    names.sort();
    names.iter().map(|n| arg_display(n)).collect()
}

fn validate_values(m: &Matcher) -> Result<(), ClapError> {
    let col = Colorizer { on: std::io::IsTerminal::is_terminal(&std::io::stderr()) };
    // clap iterates over a hash map, so the first failing argument varies
    let mut names = m.names();
    // deterministic-ish shuffle based on the pid to mimic map ordering
    let seed = std::process::id() as usize;
    names.sort_by_key(|n| (n.hash(seed)));
    for name in names {
        let entry = m.get(name).unwrap();
        if entry.occurs > 1 {
            let used = used_args(m);
            return Err(too_many(&col, name, &usage_block("executable", &used)));
        }
        if entry.vals.is_empty() {
            if let Some(o) = OPTS.iter().find(|o| o.name == name) {
                if o.default.is_none() {
                    let used = used_args(m);
                    return Err(empty_value(&col, name, &usage_block("executable", &used)));
                }
            }
            continue;
        }
        if let Err(msg) = check_value(name, &entry.vals[0]) {
            return Err(value_validation(&col, name, &msg));
        }
    }
    Ok(())
}

trait HashSeed {
    fn hash(&self, seed: usize) -> usize;
}

impl HashSeed for &str {
    fn hash(&self, seed: usize) -> usize {
        let mut h = seed as u64;
        for b in self.as_bytes() {
            h = h.wrapping_mul(31).wrapping_add(*b as u64);
        }
        h as usize
    }
}

fn check_value(name: &str, val: &str) -> Result<(), String> {
    match name {
        "count_by" | "offset" | "num" => match val.parse::<f64>() {
            Ok(_) => Ok(()),
            Err(e) => Err(e.to_string()),
        },
        "every" | "for_duration" => match duration::parse_duration(val) {
            Ok(_) => Ok(()),
            Err(e) => Err(e.to_string()),
        },
        "until_time" => match timestamp::parse_time(val) {
            Ok(_) => Ok(()),
            Err(e) => Err(e.to_string()),
        },
        "until_match" => match re::compile(val) {
            Ok(_) => Ok(()),
            Err(e) => Err(e.to_string()),
        },
        _ => Ok(()),
    }
}

fn err_text(col: &Colorizer, body: String) -> ClapError {
    ClapError {
        kind: ErrKind::Error,
        text: body,
    }
}

fn unknown_argument(col: &Colorizer, arg: &str, dym: Option<&str>, usage: &str) -> ClapError {
    let mut t = format!(
        "{} Found argument '{}' which wasn't expected, or isn't valid in this context",
        col.error("error:"),
        col.warning(arg)
    );
    if let Some(c) = dym {
        t.push_str(&format!(
            "\n\tDid you mean {}{}?",
            col.good_always("--"),
            col.good_always(c)
        ));
    }
    t.push_str(&format!(
        "\n\n{}\n\nFor more information try {}\n",
        usage,
        col.good("--help")
    ));
    err_text(col, t)
}

fn too_many(col: &Colorizer, name: &str, usage: &str) -> ClapError {
    let t = format!(
        "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}\n",
        col.error("error:"),
        col.warning(&arg_display(name)),
        usage,
        col.good("--help")
    );
    err_text(col, t)
}

fn empty_value(col: &Colorizer, name: &str, usage: &str) -> ClapError {
    let t = format!(
        "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}\n",
        col.error("error:"),
        col.warning(&arg_display(name)),
        usage,
        col.good("--help")
    );
    err_text(col, t)
}

fn value_validation(col: &Colorizer, name: &str, msg: &str) -> ClapError {
    let t = format!(
        "{} Invalid value for '{}': {}\n",
        col.error("error:"),
        col.warning(&arg_display(name)),
        msg
    );
    err_text(col, t)
}

fn parse(argv: &[std::ffi::OsString], bin: &str) -> Result<Config, ClapError> {
    let mut m = Matcher::new();
    let mut positionals: Vec<String> = Vec::new();
    let mut needs_val: Option<&'static str> = None;
    let mut trailing = false;
    let mut i = 1usize;
    while i < argv.len() {
        let a = argv[i].to_string_lossy().to_string();
        if !trailing {
            if a == "--" {
                trailing = true;
                i += 1;
                continue;
            }
            if a.starts_with("--") {
                let body = &a[2..];
                let (name, val) = match body.find('=') {
                    Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                    None => (body, None),
                };
                if let Some(o) = OPTS.iter().find(|o| o.long == name) {
                    m.touch(o.name);
                    match val {
                        Some(v) => m.add_val(o.name, v),
                        None => needs_val = Some(o.name),
                    }
                    i += 1;
                    continue;
                }
                if let Some(f) = FLAGS.iter().find(|f| f.long == name) {
                    if f.name == "help" {
                        return Err(ClapError { kind: ErrKind::Help, text: String::new() });
                    }
                    if f.name == "version" {
                        return Err(ClapError { kind: ErrKind::Version, text: String::new() });
                    }
                    m.touch(f.name);
                    i += 1;
                    continue;
                }
                let dym = did_you_mean(name);
                let mut names: Vec<&'static str> = m.names();
                names.sort();
                let used: Vec<String> = if let Some(c) = dym {
                    let mut v: Vec<&'static str> = m.names();
                    if let Some(o) = OPTS.iter().find(|o| o.long == c) {
                        v.push(o.name);
                    } else if let Some(f) = FLAGS.iter().find(|f| f.long == c) {
                        v.push(f.name);
                    }
                    v.sort();
                    v.iter().map(|n| arg_display(n)).collect()
                } else {
                    names.iter().map(|n| arg_display(n)).collect()
                };
                return Err(unknown_argument(
                    &Colorizer { on: std::io::IsTerminal::is_terminal(&std::io::stderr()) },
                    &a,
                    dym,
                    &usage_block(bin, &used),
                ));
            }
            if a.starts_with('-') && a.len() > 1 {
                let chars: Vec<char> = a[1..].chars().collect();
                let mut j = 0usize;
                while j < chars.len() {
                    let c = chars[j];
                    if let Some(f) = FLAGS.iter().find(|f| f.short == Some(c)) {
                        if f.name == "help" {
                            return Err(ClapError { kind: ErrKind::Help, text: String::new() });
                        }
                        if f.name == "version" {
                            return Err(ClapError { kind: ErrKind::Version, text: String::new() });
                        }
                        m.touch(f.name);
                        j += 1;
                        continue;
                    }
                    if let Some(o) = OPTS.iter().find(|o| o.short == Some(c)) {
                        m.touch(o.name);
                        let rest: String = chars[j + 1..].iter().collect();
                        if rest.is_empty() {
                            needs_val = Some(o.name);
                        } else if let Some(r) = rest.strip_prefix('=') {
                            m.add_val(o.name, r.to_string());
                        } else {
                            m.add_val(o.name, rest);
                        }
                        j = chars.len();
                        break;
                    }
                    let arg = format!("-{}", c);
                    let mut names: Vec<&'static str> = m.names();
                    names.sort();
                    let used: Vec<String> = names.iter().map(|n| arg_display(n)).collect();
                    return Err(unknown_argument(
                        &Colorizer { on: std::io::IsTerminal::is_terminal(&std::io::stderr()) },
                        &arg,
                        None,
                        &usage_block(bin, &used),
                    ));
                }
                i += 1;
                continue;
            }
        }
        if let Some(name) = needs_val.take() {
            m.add_val(name, a);
        } else {
            positionals.push(a);
        }
        i += 1;
    }
    add_defaults(&mut m);
    if let Err(e) = validate_values(&m) {
        return Err(e);
    }
    if positionals.is_empty() {
        return Err(ClapError { kind: ErrKind::NoCommand, text: String::new() });
    }
    // build the config
    let cmd = positionals.join(" ");
    let every = duration::parse_duration(m.value("every").unwrap()).unwrap();
    let for_duration = match m.value("for_duration") {
        Some(v) => Some(duration::parse_duration(v).unwrap()),
        None => None,
    };
    let until_time = match m.value("until_time") {
        Some(v) => Some(timestamp::parse_time(v).unwrap()),
        None => None,
    };
    let until_match = match m.value("until_match") {
        Some(v) => Some(re::compile(v).unwrap()),
        None => None,
    };
    let offset: f64 = m.value("offset").unwrap().parse().unwrap();
    let count_by: f64 = m.value("count_by").unwrap().parse().unwrap();
    let num: f64 = match m.value("num") {
        Some(v) => v.parse().unwrap(),
        None => 0.0,
    };
    let cb_str = m.value("count_by").unwrap();
    let decimals = match cb_str.find('.') {
        Some(p) => cb_str[p + 1..].chars().count(),
        None => 0,
    };
    let for_list = m.value("ffor").map(|v| v.split(',').map(|s| s.to_string()).collect());
    let read_stdin = m.has("stdin");
    let cfg = Config {
        cmd,
        every,
        num: num.trunc() as i64,
        offset,
        count_by,
        decimals,
        for_list,
        read_stdin,
        only_last: m.has("only_last"),
        summary: m.has("summary"),
        error_duration: m.has("error_duration"),
        until_changes: m.has("until_changes"),
        until_fail: m.has("until_fail"),
        until_same: m.has("until_same"),
        until_success: m.has("until_success"),
        until_contains: m.value("until_contains").map(|v| v.to_string()),
        until_error: m.value("until_error").and_then(|v| v.parse::<i32>().ok()),
        until_match,
        until_time,
        for_duration,
    };
    Ok(cfg)
}

fn now_moment() -> (u64, u32) {
    match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(d) => (d.as_secs(), d.subsec_nanos()),
        Err(_) => (0, 0),
    }
}

fn print_output(s: &str) {
    for line in s.lines() {
        println!("{}", line);
    }
}

fn exec(cmd: &str) -> (String, i32) {
    let (mut file, path) = capture_file();
    let _ = fs::remove_file(&path);
    let out = file.try_clone().expect("clone stdout");
    let errout = file.try_clone().expect("clone stderr");
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .stdin(Stdio::inherit())
        .stdout(Stdio::from(out))
        .stderr(Stdio::from(errout))
        .spawn()
        .expect("spawn failed");
    let status = child.wait().expect("wait failed");
    let text = read_capture(&mut file);
    (text, status.code().unwrap_or(99))
}

fn run(cfg: &Config) -> i32 {
    let mut items: Vec<String> = Vec::new();
    if let Some(l) = &cfg.for_list {
        items.extend(l.iter().cloned());
    }
    if cfg.read_stdin || !std::io::IsTerminal::is_terminal(&std::io::stdin()) {
        let mut buf = String::new();
        let _ = std::io::Read::read_to_string(&mut std::io::stdin(), &mut buf);
        for line in buf.lines() {
            items.push(line.to_string());
        }
    }
    let mut item_idx = 0usize;
    let mut count: f64 = cfg.offset;
    let mut runs: i64 = 0;
    let mut first_output: Option<String> = None;
    let mut last_out: Option<String> = None;
    let mut successes: u64 = 0;
    let mut failures: u64 = 0;
    let mut codes: Vec<i32> = Vec::new();
    let mut ended_by_duration = false;
    let start = Instant::now();
    loop {
        if runs >= cfg.num {
            break;
        }
        if let Some(d) = &cfg.for_duration {
            if start.elapsed() >= *d {
                ended_by_duration = true;
                break;
            }
        }
        if let Some(t) = &cfg.until_time {
            let (s, n) = now_moment();
            if s > t.secs || (s == t.secs && n >= t.nanos) {
                break;
            }
        }
        if item_idx < items.len() {
            env::set_var("ITEM", &items[item_idx]);
            item_idx += 1;
        }
        env::set_var("COUNT", format!("{:.*}", cfg.decimals, count));
        env::set_var("ACTUALCOUNT", format!("{}", runs));
        let (output, code) = exec(&cfg.cmd);
        if !cfg.only_last {
            print_output(&output);
        } else {
            last_out = Some(output.clone());
        }
        if code == 0 {
            successes += 1;
        } else {
            failures += 1;
            codes.push(code);
        }
        let mut stop = false;
        if let Some(f) = &first_output {
            if cfg.until_changes && f != &output {
                stop = true;
            }
            if cfg.until_same && f == &output {
                stop = true;
            }
        }
        if let Some(needle) = &cfg.until_contains {
            if output.lines().any(|l| l.contains(needle.as_str())) {
                stop = true;
            }
        }
        if let Some(rx) = &cfg.until_match {
            if output.lines().any(|l| rx.is_match(l)) {
                stop = true;
            }
        }
        if cfg.until_success && code == 0 {
            stop = true;
        }
        if cfg.until_fail && code != 0 {
            stop = true;
        }
        if let Some(v) = cfg.until_error {
            if v == code {
                stop = true;
            }
        }
        if first_output.is_none() {
            first_output = Some(output);
        }
        if stop {
            break;
        }
        runs += 1;
        count += cfg.count_by;
        let target = start + cfg.every * runs as u32;
        let now = Instant::now();
        if target > now {
            std::thread::sleep(target - now);
        }
    }
    if cfg.only_last {
        if let Some(o) = last_out {
            print_output(&o);
        }
    }
    if cfg.summary {
        println!("Total runs:\t{}", successes + failures);
        println!("Successes:\t{}", successes);
        if failures > 0 {
            let list: Vec<String> = codes.iter().map(|c| c.to_string()).collect();
            println!("Failures:\t{} ({})", failures, list.join(", "));
        } else {
            println!("Failures:\t0");
        }
    }
    if ended_by_duration && cfg.error_duration {
        return 124;
    }
    0
}

fn main() {
    let args: Vec<std::ffi::OsString> = env::args_os().collect();
    let bin = bin_name(&args[0]);
    match parse(&args, &bin) {
        Ok(cfg) => {
            let code = run(&cfg);
            std::process::exit(code);
        }
        Err(e) => match e.kind {
            ErrKind::Help => {
                print!("{}", help_text(&bin));
                std::process::exit(0);
            }
            ErrKind::Version => {
                println!("{} {}", APP, VER);
                std::process::exit(0);
            }
            ErrKind::NoCommand => {
                println!("No command supplied, exiting.");
                std::process::exit(0);
            }
            _ => {
                eprint!("{}", e.render());
                std::process::exit(1);
            }
        },
    }
}
