fn jaro_winkler(a: &str, b: &str) -> f64 {
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    let (al, bl) = (ac.len(), bc.len());
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    if al == 1 && bl == 1 {
        return if ac[0] == bc[0] { 1.0 } else { 0.0 };
    }
    let sr = (std::cmp::max(al, bl) / 2) - 1;
    let mut bconsumed = vec![false; bl];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut bmi = 0usize;
    for i in 0..al {
        let minb = if i > sr { std::cmp::max(0, i - sr) } else { 0 };
        let maxb = std::cmp::min(bl - 1, i + sr);
        if minb > maxb {
            continue;
        }
        for j in 0..bl {
            if minb <= j && j <= maxb && ac[i] == bc[j] && !bconsumed[j] {
                bconsumed[j] = true;
                matches += 1.0;
                if j < bmi {
                    transpositions += 1.0;
                }
                bmi = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        return 0.0;
    }
    let jaro = (1.0 / 3.0)
        * ((matches / al as f64) + (matches / bl as f64) + ((matches - transpositions) / matches));
    let mut prefix = 0usize;
    for k in 0..std::cmp::min(al, bl) {
        if ac[k] == bc[k] {
            prefix += 1;
        } else {
            break;
        }
    }
    let jw = jaro + (0.1 * prefix as f64 * (1.0 - jaro));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

fn did_you_mean(arg: &str) -> Option<&'static str> {
    let mut cands: Vec<&'static str> = Vec::new();
    for o in OPTS.iter() {
