new = r'''    // escape inside a character class; returns the parsed piece
    fn class_escape(&mut self) -> R<ClsEsc> {
        let es = self.i;
        self.bump(); // '\'
        let e = match self.peek() {
            Some(e) => e,
            None => {
                return Err(self.e1(
                    "incomplete escape sequence, reached end of pattern prematurely",
                    es,
                ));
            }
        };
        self.bump();
        let (p, n) = match e {
            'd' => (Some(Posix::Digit), false),
            'D' => (Some(Posix::Digit), true),
            'w' => (Some(Posix::Word), false),
            'W' => (Some(Posix::Word), true),
            's' => (Some(Posix::Space), false),
            'S' => (Some(Posix::Space), true),
            _ => (None, false),
        };
        if let Some(p) = p {
            return Ok(ClsEsc::Set(class_posix_cls(p, n)));
        }
        if e == 'p' || e == 'P' {
            let mut name = String::new();
            let mut end = self.i;
            if self.peek() == Some('{') {
                self.bump();
                while let Some(ch) = self.peek() {
                    if ch == '}' {
                        self.bump();
                        break;
                    }
                    name.push(ch);
                    self.bump();
                }
                end = self.i;
            } else if let Some(ch) = self.peek() {
