                    name.push(self.c[j]);
                    j += 1;
                }
                if found {
                    if let Some(p) = posix_by_name(&name) {
                        items.push(Item::Posix(p));
                        self.i = j + 2;
                        continue;
                    }
                }
                self.i = save;
                if let Node::Class(cl) = self.class()? {
                    items.push(Item::Class(cl));
                }
                continue;
            }
            if c == '[' {
