                                    if h < ch {
                                        return Err(self.err(
                                            "invalid character class range, the start must be <= the end",
                                            vec![(lo_pos, self.i)],
                                        ));
                                    }
                                    items.push(Item::Range(ch, h));
                                }
                                _ => {
                                    return Err(self.err(
                                        "invalid range boundary, must be a literal",
                                        vec![(self.i, self.i)],
                                    ));
                                }
                            }
                        } else {
                            items.push(Item::Range(ch, ch));
                        }
                    }
                    ClsEsc::Set(cl) => {
                        if self.peek() == Some('-')
                            && self.at(self.i + 1).is_some()
                            && self.at(self.i + 1) != Some(']')
