                    Some('\\') => {
                        let es = self.i;
                        match self.class_escape()? {
                            ClsEsc::Lit(v) => hi = Some(v),
                            _ => {
                                return Err(self.err(
                                    "invalid range boundary, must be a literal",
                                    vec![(es, self.i)],
                                ));
                            }
                        }
                    }
                    Some(ch) => {
                        self.bump();
                        hi = Some(ch);
                    }
                    None => {
                        return Err(self.e1(
                            "incomplete escape sequence, reached end of pattern prematurely",
                            self.i,
                        ));
                    }
                }
            }
            match hi {
                Some(h) => {
                    if h < lo {
                        return Err(self.err(
                            "invalid character class range, the start must be <= the end",
                            vec![(lo_pos, self.i)],
                        ));
                    }
                    items.push(Item::Range(lo, h));
                }
                None => items.push(Item::Range(lo, lo)),
            }
        }
        Ok(Node::Class(Class { items, neg }))
    }
}

enum ClsEsc {
    Lit(char),
    Set(Class),
    Prop(String, bool),
}

