fn make_capture_file(path: &std::path::Path) -> std::io::Result<File> {
    OpenOptions::new().read(true).write(true).create_new(true).open(path)
}

// The capture file is created, unlinked right away and then handed to the child
// as both stdout and stderr, so nothing is ever left behind on disk.
fn capture_file() -> (File, std::path::PathBuf) {
    let dir = env::temp_dir();
    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(12345);
    seed ^= (std::process::id() as u64).wrapping_mul(0x9e3779b97f4a7c15);
    let name = rand_name(&mut seed);
    let path = dir.join(name);
    let capture = make_capture_file(&path).unwrap();
    (capture, path)
}

// Read back what the child wrote and turn it into text.  The file descriptor is
// shared with the child, so it has to be rewound first.
fn read_capture(capture: &mut File) -> String {
        capture.read_to_string(&mut buffer).expect("read failed");
    buffer
}

