                        let mut name = String::new();
                        loop {
                            match self.peek() {
                                Some('>') => {
                                    self.bump();
                                    break;
                                }
                                Some(c) if c.is_alphanumeric() || c == '_' => {
                                    name.push(c);
                                    self.bump();
                                }
                                Some(_) => {
                                    return Err(self.e1(
