                                    return Err(self.err("duplicate flag", spans));
                                }
                                seen.push((f, self.i));
                                match f {
                                    'i' => self.flags.ci = !neg,
                                    'U' => self.flags.swap = !neg,
                                    'x' => self.flags.x = !neg,
                                    _ => {}
                                }
