{"command": "cd /workspace && python3 - <<'PYEOF'
p='src/re.rs'
lines=open(p).read().split('\n')
# replace from the matcher section header (line 1176) to just before "pub fn compile"
start = 1176 - 1            # 0-based index of the matcher header
comp = next(i for i,l in enumerate(lines) if l.startswith("pub fn compile"))
new = r'''// ---------------------------------------------------------------- matcher
//
// The pattern is compiled into a small NFA and simulated with the classic
// "set of threads" algorithm, which is linear in the length of the input and
// therefore immune to the kind of exponential blow-up that backtracking
// engines suffer from on nested repetitions.  Only `is_match` is needed, so
// captures and greediness can be ignored.

#[derive(Clone)]
enum Inst {
    Char(char, bool),
    Class(Class),
    Any,
    AnyNl,
    Split(usize, usize),
    Jmp(usize),
    StartLine,
    EndLine,
    StartText,
    EndText,
    WordB,
    NotWordB,
    Match,
}

pub struct Regex {
    prog: Vec<Inst>,
}

struct Compiler {
    prog: Vec<Inst>,
    groups: u64,
}

impl Compiler {
    fn emit_nodes(&mut self, nodes: &[Node]) {
        for n in nodes {
            self.emit_node(n);
        }
    }

    fn emit_node(&mut self, node: &Node) {
        match node {
            Node::Lit(c, ci) => self.prog.push(Inst::Char(*c, *ci)),
            Node::Any => self.prog.push(Inst::Any),
            Node::Class(cl) => self.prog.push(Inst::Class(cl.clone())),
            Node::StartLine => self.prog.push(Inst::StartLine),
            Node::EndLine => self.prog.push(Inst::EndLine),
            Node::StartText => self.prog.push(Inst::StartText),
            Node::EndText => self.prog.push(Inst::EndText),
            Node::WordB => self.prog.push(Inst::WordB),
            Node::NotWordB => self.prog.push(Inst::NotWordB),
            Node::Group(seq) => {
                self.groups += 1;
                self.emit_nodes(seq);
            }
            Node::Alt(branches) => {
                let mut jumps = Vec::new();
                let last = branches.len() - 1;
                for (i, b) in branches.iter().enumerate() {
                    if i == last {
                        self.emit_nodes(b);
                    } else {
                        let split = self.prog.len();
                        self.prog.push(Inst::Jmp(0));
                        self.emit_nodes(b);
                        let jmp = self.prog.len();
                        self.prog.push(Inst::Jmp(0));
                        jumps.push(jmp);
                        let next = self.prog.len();
                        self.prog[split] = Inst::Split(split + 1, next);
                    }
                }
                let end = self.prog.len();
                for j in jumps {
                    self.prog[j] = Inst::Jmp(end);
                }
            }
            Node::Rep {
                seq,
                min,
                max,
                ..
            } => {
                for _ in 0..*min {
                    self.emit_nodes(seq);
                }
                match max {
                    None => {
                        let split = self.prog.len();
                        self.prog.push(Inst::Jmp(0));
                        self.emit_nodes(seq);
                        self.prog.push(Inst::Jmp(split));
                        let exit = self.prog.len();
                        self.prog[split] = Inst::Split(split + 1, exit);
                    }
                    Some(m) => {
                        let extra = m.saturating_sub(*min);
                        let mut splits = Vec::new();
                        for _ in 0..extra {
                            let split = self.prog.len();
                            self.prog.push(Inst::Jmp(0));
                            splits.push(split);
                            self.emit_nodes(seq);
                        }
                        let end = self.prog.len();
                        for s in splits {
                            self.prog[s] = Inst::Split(s + 1, end);
                        }
                    }
                }
            }
        }
    }
}

impl Regex {
    /// add `pc` and everything reachable from it without consuming input
    fn add_thread(
        &self,
        list: &mut Vec<usize>,
        on: &mut Vec<bool>,
        stack: &mut Vec<usize>,
        pc: usize,
        pos: usize,
        chars: &[char],
    ) {
        if on[pc] {
            return;
        }
        on[pc] = true;
        list.push(pc);
        let follow = match self.prog[pc] {
            Inst::Jmp(x) => Some(x),
            Inst::Split(x, _) => Some(x),
            Inst::StartLine => {
                if pos == 0 {
                    Some(pc + 1)
                } else {
                    None
                }
            }
            Inst::StartText => {
                if pos == 0 {
                    Some(pc + 1)
                } else {
                    None
                }
            }
            Inst::EndLine | Inst::EndText => {
                if pos == chars.len() {
                    Some(pc + 1)
                } else {
                    None
                }
            }
            Inst::WordB => {
                if at_word_boundary(chars, pos) {
                    Some(pc + 1)
                } else {
                    None
                }
            }
            Inst::NotWordB => {
                if !at_word_boundary(chars, pos) {
                    Some(pc + 1)
                } else {
                    None
                }
            }
            Inst::Split(_, y) => Some(y),
            _ => None,
        };
        if let Some(f) = follow {
            stack.push(f);
        }
    }

    fn closure(
        &self,
        list: &mut Vec<usize>,
        on: &mut Vec<bool>,
        seeds: &[usize],
        pos: usize,
        chars: &[char],
    ) {
        let mut stack: Vec<usize> = Vec::new();
        for s in seeds {
            stack.push(*s);
        }
        while let Some(pc) = stack.pop() {
            self.add_thread(list, on, &mut stack, pc, pos, chars);
        }
    }

    pub fn is_match(&self, text: &str) -> bool {
        let chars: Vec<char> = text.chars().collect();
        let n = chars.len();
        let m = self.prog.len();
        let mut clist: Vec<usize> = Vec::new();
        let mut nlist: Vec<usize> = Vec::new();
        let mut on_c = vec![false; m];
        let mut on_n = vec![false; m];
        // the pattern is unanchored: the first instruction splits between
        // trying the pattern here and skipping one character
        self.closure(&mut clist, &mut on_c, &[0], 0, &chars);
        for pos in 0..=n {
            for pc in clist.iter() {
                if let Inst::Match = self.prog[*pc] {
                    return true;
                }
            }
            if pos == n {
                break;
            }
            let c = chars[pos];
            for pc in clist.iter() {
                let hit = match &self.prog[*pc] {
                    Inst::Char(ch, ci) => *ch == c || (*ci && ci_eq(c, *ch)),
                    Inst::Class(cl) => cl.matches(c, cl.ci),
                    Inst::Any => c != '\n',
                    Inst::AnyNl => true,
                    _ => false,
                };
                if hit {
                    if !on_n[*pc + 1] {
                        on_n[*pc + 1] = true;
                        nlist.push(*pc + 1);
                    }
                }
            }
            for pc in clist.iter() {
                on_c[*pc] = false;
            }
            clist.clear();
            let seeds: Vec<usize> = nlist.clone();
            for pc in nlist.iter() {
                on_n[*pc] = false;
            }
            nlist.clear();
            // a new attempt may start at every position
            let mut all = seeds;
            all.push(0);
            self.closure(&mut clist, &mut on_c, &all, pos + 1, &chars);
        }
        false
    }
}

fn at_word_boundary(text: &[char], pos: usize) -> bool {
    let before = if pos == 0 { None } else { Some(text[pos - 1]) };
    let after = text.get(pos).copied();
    let b = before.map_or(false, is_word);
    let a = after.map_or(false, is_word);
    b != a
}

