    let chars: Vec<char> = pat.chars().collect();
    let mut p = Parser {
        pat: pat.to_string(),
        c: chars,
        i: 0,
        flags: Flags::new(),
        names: Vec::new(),
    };
    let root = p.parse()?;
    let mut c = Compiler {
        prog: Vec::new(),
        groups: 0,
    };
    // unanchored search: skip any number of characters before matching
    c.prog.push(Inst::Jmp(0)); // placeholder for the leading split
    match &root {
        Node::Alt(branches) => c.emit_nodes(&[root.clone()]),
        other => c.emit_nodes(std::slice::from_ref(other)),
    }
    c.prog.push(Inst::Match);
    let split_end = c.prog.len();
    c.prog.push(Inst::AnyNl);
    c.prog.push(Inst::Jmp(0));
    c.prog[0] = Inst::Split(1, split_end);
    c.prog[split_end + 1] = Inst::Jmp(0);
    let size = c.prog.len() as u64 + c.groups * 2;
    if size * 32 > 10485760 {
        return Err(RegexError {
            pattern: pat.to_string(),
            spans: Vec::new(),
            msg: "Compiled regex exceeds size limit of 10485760 bytes.".to_string(),
            parse: false,
        });
    }
    Ok(Regex { prog: c.prog })
}
