    Class(Class),
    Any,
    AnyNl,
    Split(usize, usize),
    Jmp(usize),
    StartLine,
    EndLine,
    StartText,
    EndText,
    WordB,
    NotWordB,
    Match,
}

pub struct Regex {
    prog: Vec<Inst>,
}

struct Compiler {
    prog: Vec<Inst>,
    groups: u64,
