        }
    }

    fn closure(
        &self,
        list: &mut Vec<usize>,
        on: &mut Vec<bool>,
        seeds: &[usize],
        pos: usize,
        chars: &[char],
    ) {
        let mut stack: Vec<usize> = Vec::new();
        for s in seeds {
            stack.push(*s);
