                    if !on_n[*pc + 1] {
                        on_n[*pc + 1] = true;
                        nlist.push(*pc + 1);
                    }
                }
            }
            for pc in clist.iter() {
                on_c[*pc] = false;
            }
            clist.clear();
            let seeds: Vec<usize> = nlist.clone();
            for pc in nlist.iter() {
                on_n[*pc] = false;
            }
            nlist.clear();
            // a new attempt may start at every position
            let mut all = seeds;
            all.push(0);
            self.closure(&mut clist, &mut on_c, &all, pos + 1, &chars);
        }
        false
    }
}

fn at_word_boundary(text: &[char], pos: usize) -> bool {
    let before = if pos == 0 { None } else { Some(text[pos - 1]) };
    let after = text.get(pos).copied();
    let b = before.map_or(false, is_word);
    let a = after.map_or(false, is_word);
    b != a
}

